/* Stages 3-4 lessons. Schema: intro, question, analogy, analogyFail, explain[], tech[], code, codeNotes[], output, why, lang, interactive, sim, mistakes[], practices[], quiz[], takeaways[], recall, todo, anim{title,steps[]} */
export const LESSONS_B={
'boolean-expr':{intro:'Every decision a program makes starts as a yes/no question. Boolean expressions answer true or false — they are the electricity that powers all logic.',question:'How does a bouncer decide in a single glance who gets in?',analogy:'The bouncer’s checklist: age ≥ 18? AND on the list? NOT banned? Each check is true/false, and the combined verdict lifts the rope.',analogyFail:'Where it breaks: bouncers bend rules for friends. Booleans never bend — exactly true or false, with no “maybe”, no “sort of”, ever.',explain:['<b>Comparisons</b> produce booleans: == != < <= > >=. The expression 5 > 3 IS the value true — it can be stored, printed, and combined.','<b>Logic operators</b> combine them: <b>&&</b> demands both sides true, <b>||</b> settles for either, <b>!</b> flips. Binding order: ! first, then comparisons, then &&, then ||.','<b>Text</b> compares with .equals(), never == — == asks “same object?”, equals asks “same content?”.','<b>Short-circuit</b> evaluation stops the moment the answer is decided: false && ANYTHING skips the right side entirely. That skipping is load-bearing — guards like (s != null && s.length() > 0) depend on it.'],tech:['<b>boolean</b> is a real type, not 0/1: boolean b = (5 > 3); stores true. There is no truthy/falsy like JavaScript — conditions DEMAND boolean.','<b>De Morgan’s laws</b>: !(a && b) equals !a || !b. Negating “both” gives “at least one fails” — the single most useful logic rewrite.','<b>==</b> on primitives compares VALUES (3 == 3 is true); on objects it compares IDENTITY. Two different rules, one symbol — hence the .equals habit.'],code:`public class Main {\n  public static void main(String[] args) {\n    int age = 20;\n    boolean canVote = age >= 18;\n    boolean vip = age >= 18 && age < 65;\n    boolean deny = !(age >= 18);\n    System.out.println(canVote);\n    System.out.println(vip);\n    System.out.println(deny);\n  }\n}`,codeNotes:['>= asks a true/false question and stores the answer.','&& needs both halves true: 20 passes both.','! flips true into false.'],output:'true\ntrue\nfalse',why:'20 ≥ 18 is true; 20 < 65 is also true, so vip is true; deny negates a true into false.',sim:{kind:'cond',label:'Bouncer test: try different ages.',fields:[{v:'20'}]},mistakes:[{bad:'if (age = 18) with one equals sign.',why:'That STORES 18 instead of asking — an int is not a boolean, so it does not even compile in a condition.',fix:'Ask with two: if (age == 18).'},{bad:'"abc" == "abc" to compare text.',why:'Identity comparison — two equal-content objects are usually different houses.',fix:'Content needs equals: s.equals("abc").'},{bad:' true && false confidently called true.',why:'AND is greedy: one false poisons the whole chain.',fix:'Truth-table it: T && F = F, T || F = T.'}],practices:[{title:'Bouncer logic',task:'Write canEnter from age (≥ 18) and hasTicket (boolean).',hint:'Both must hold — which operator?',sol:'boolean canEnter = age >= 18 && hasTicket;'},{title:'Apply De Morgan',task:'Rewrite !(a && b) using || instead of &&.',hint:'Flip each side, flip the operator.',sol:'boolean r = !a || !b; — test with a truth table.'}],quiz:[{id:'q1',prompt:'5 > 3 && 2 > 9 evaluates to…',options:[{t:'false',ok:true},{t:'true'},{t:'maybe'},{t:'A compiler error'}],explain:'T && F = F. AND shows no mercy.'},{id:'q2',prompt:'!true || false equals…',options:[{t:'false',ok:true},{t:'true'},{t:'A compiler error'},{t:'null'}],explain:'!true is F; F || F stays F.'},{id:'q3',prompt:'String contents are compared with…',options:[{t:'.equals()',ok:true},{t:'=='},{t:'='},{t:'==='}],explain:'Content comparison is equals; == is identity.'},{id:'q4',prompt:'(s != null && s.length() > 0) with s == null is safe because…',options:[{t:'&& stops at the first false, so length() never runs',ok:true},{t:'null has length 0'},{t:'Java ignores the right side always'},{t:'Exceptions are disabled'}],explain:'Short-circuit is the guardrail — the crash never gets a chance.'}],takeaways:['Booleans are exactly true or false — never 0/1, never maybe.','&& needs both, || needs one, ! flips.','Text compares with equals; == is identity.','Short-circuit makes null-guards safe.'],recall:'State De Morgan’s law and say when you would use it.',todo:'Write 3 boolean rules for a game you like, using &&, ||, and !.',anim:{title:'Bouncer checklist',steps:[{caption:'Question 1: age ≥ 18? → true.',html:'<div class="viz"><div class="varbox"><div class="nm">age ≥ 18</div><div class="vl">true</div></div></div>'},{caption:'Question 2: has a ticket? → true.',html:'<div class="viz"><div class="varbox"><div class="nm">ticket</div><div class="vl">true</div></div></div>'},{caption:'AND: both true → enter. ✓',html:'<div class="pipe"><div class="box">true && true</div><span class="arr">→</span><div class="box"><b>enter ✓</b></div></div>'}]}},
'if-else':{intro:'if lets programs CHOOSE. One question, two futures — the code walks exactly one path and skips the other. Most “intelligence” in software is just well-arranged choices.',question:'What can traffic lights do that a straight open road cannot?',analogy:'A fork on a trek path with a sign: “raining? left to shelter — else right to the viewpoint.” You walk exactly one branch, never both, and the sign decides which.',analogyFail:'Where it breaks: trekkers can turn back and try the other fork. Code cannot un-run a branch — each run commits to one path permanently.',explain:['Shape: <b>if (cond) { } else if (cond) { } else { }</b>. The FIRST true branch runs; everything else is skipped, including all later else-ifs.','Order conditions <b>specific → general</b>: test ≥ 90 before ≥ 75, or the 90s get swallowed by the 75s and grade A becomes unreachable.','The final <b>else</b> catches everything left over — the safety net. Leave it off only when “do nothing” is genuinely correct.','Braces are armor: a braceless if controls exactly ONE following statement, and the classic bug is adding a second line that silently escapes the if. Always brace.'],tech:['An if-chain is <b>exclusive</b>: at most ONE branch runs. Separate ifs are <b>independent</b>: several can fire. Choosing wrong between them is a top-5 beginner bug.','<b>if (x > 5);</b> with a stray semicolon is an EMPTY if — the block below always runs. The compiler stays silent; only your eyes catch it.','Conditions must be <b>boolean</b>: if (5) and if ("yes") do not compile. No truthy/falsy shortcuts in Java.'],code:`public class Main {\n  public static void main(String[] args) {\n    int marks = 82;\n    if (marks >= 90) {\n      System.out.println("Grade A");\n    } else if (marks >= 75) {\n      System.out.println("Grade B");\n    } else if (marks >= 60) {\n      System.out.println("Grade C");\n    } else {\n      System.out.println("Keep going");\n    }\n  }\n}`,codeNotes:['82 fails ≥ 90, passes ≥ 75 → Grade B.','Only that one branch prints; the rest are skipped.','The else is the net catching everything below 60.'],output:'Grade B',why:'First true condition wins and the chain exits immediately — later branches never even evaluate.',sim:{kind:'cond',label:'Try different marks; watch which branch fires.',fields:[{v:'82'}]},mistakes:[{bad:'if (marks = 90) with single =.',why:'Assignment, not a question — and an int is not boolean, so it fails loudly.',fix:'Ask with double: if (marks == 90).'},{bad:'Two separate ifs where one chain was meant.',why:'Independent ifs can BOTH fire (≥75 AND ≥60 both print) — exclusive choice needs else-if.',fix:'Chain them: if / else if / else.'},{bad:'if (x > 5); { launch(); } with a stray semicolon.',why:'The semicolon IS the if-body (empty); launch() always runs, checked or not.',fix:'Delete the semicolon. Then brace everything.'},{bad:'Testing ≥ 60 BEFORE ≥ 90 in the chain.',why:'The general net catches everything first; Grade A becomes dead code.',fix:'Order specific → general, always.'}],practices:[{title:'Grade it',task:'marks = 45. Trace the chain and name the exact output.',hint:'Fall through each failing check.',sol:'Fails 90, 75, 60 → else prints “Keep going”.'},{title:'Even or odd',task:'Print “even” when n % 2 == 0, else “odd”.',hint:'One if, one else.',sol:'if (n % 2 == 0) { System.out.println("even"); } else { System.out.println("odd"); }'}],quiz:[{id:'q1',prompt:'marks = 95 prints…',options:[{t:'Grade A',ok:true},{t:'Grade B'},{t:'Both A and B'},{t:'Nothing'}],explain:'First true branch wins; the chain exits at ≥ 90.'},{id:'q2',prompt:'How many branches of one if-chain can run?',options:[{t:'At most one',ok:true},{t:'All true ones'},{t:'Always exactly two'},{t:'Zero or all'}],explain:'Exclusivity is the whole point of else-if.'},{id:'q3',prompt:'if (x > 5); { go(); } is dangerous because…',options:[{t:'The semicolon silently ends the if; go() always runs',ok:true},{t:'x is too small'},{t:'Braces are missing'},{t:'Java dislikes x'}],explain:'An empty statement swallows the entire condition.'},{id:'q4',prompt:'Checking ≥ 60 before ≥ 90 breaks grading because…',options:[{t:'The general case swallows the specific one',ok:true},{t:'90 is not a number'},{t:'Else is required first'},{t:'Marks cannot exceed 60'}],explain:'Order specific → general, or top grades die.'}],takeaways:['First true branch runs; the rest are skipped.','Order conditions specific → general.','else-if = exclusive; separate ifs = independent.','No stray semicolons; always brace.'],recall:'Why does branch ORDER change program meaning?',todo:'Write a rain-or-shine weekend planner with a 3-branch chain.',anim:{title:'Fork in the path',steps:[{caption:'Ask: marks ≥ 90? No — walk on.',html:'<div class="pipe"><div class="box">≥90? ❌</div></div>'},{caption:'Ask: marks ≥ 75? Yes → Grade B.',html:'<div class="pipe"><div class="box">≥75? ✓</div><span class="arr">→</span><div class="box"><b>Grade B</b></div></div>'},{caption:'Everything below is skipped unseen.',html:'<div class="pipe"><div class="box">else ignored</div></div>'}]}},
'nested-cond':{intro:'Real decisions stack: inside “is it the weekend?” sits “is it sunny?”. Nesting handles layered reality — but each level multiplies the paths you must test, so flatten whenever you can.',question:'When is a box inside a box clearer than two boxes side by side?',analogy:'Russian dolls. The outer doll asks “weekend?”; only if YES do you open it and find “sunny?” inside. Two levels read fine; five dolls deep and nobody remembers which doll they are in.',analogyFail:'Where it breaks: dolls always fit together perfectly. Nested ifs hide paths EXPONENTIALLY — 3 levels ≈ 8 paths to test, and untested paths are where bugs breed.',explain:['<b>Nesting</b> = an if inside an if. The inner question is asked ONLY when the outer answer is true; otherwise the whole inner world never happens.','Flatten when the inner needs nothing else: <b>if (a && b)</b> replaces two levels with one, halving the paths. Professionals flatten aggressively.','The <b>dangling else</b> rule: an else pairs with the NEAREST open if. Without braces, “which if does this else belong to?” becomes a riddle — always brace nested code.','Trace nested code with a path table: list every outer/inner true-false combo and the line each combo reaches. If you cannot enumerate the paths, the nesting is too deep.'],tech:['Cyclomatic <b>complexity</b> roughly counts paths through code; each if/loop/case adds one. Pros keep methods near 10 — deep nesting blows past it fast.','<b>Guard clauses</b> (early return on bad input) flatten nesting without &&: reject first, then the main logic sits at depth one.','Flattening with && is valid only when the inner block has NO else of its own — an inner else needs real nesting.'],code:`public class Main {\n  public static void main(String[] args) {\n    boolean weekend = true;\n    boolean sunny = false;\n    if (weekend) {\n      if (sunny) {\n        System.out.println("Picnic");\n      } else {\n        System.out.println("Museum");\n      }\n    } else {\n      System.out.println("Work");\n    }\n  }\n}`,codeNotes:['Outer true → step inside.','Inner false → its else prints Museum.','Braces make every pairing unambiguous.'],output:'Museum',why:'Weekend true opens the outer doll; sunny false selects the inner else. “Work” needed outer false.',sim:{kind:'cond',label:'Layered logic: weekend decides, then weather.',fields:[{v:'18'}]},mistakes:[{bad:'Dangling else, braceless: if (a) if (b) X; else Y;',why:'The else secretly belongs to the INNER if — readers (and you, later) will misread it.',fix:'Brace every nested if, no exceptions.'},{bad:'Five levels of nesting “to be safe”.',why:'32 paths, most untested — a bug farm with extra steps.',fix:'Flatten with &&, or guard-clause the failures out early.'},{bad:'Checking inner details before validating the outer.',why:'Null or empty outer data detonates before the inner question matters.',fix:'Outer validates first: null-checks live OUTSIDE.'}],practices:[{title:'Flatten it',task:'Flatten this into one condition: if (a) { if (b) { go(); } }',hint:'One &&, one level.',sol:'if (a && b) { go(); }'},{title:'Count the paths',task:'An if containing an if-else: how many distinct paths? Name them.',hint:'Outer true/false × inner…',sol:'Three: outer-false; outer-true + inner-true; outer-true + inner-false. (Inner never runs when outer is false.)'}],quiz:[{id:'q1',prompt:'weekend = false prints…',options:[{t:'Work',ok:true},{t:'Picnic'},{t:'Museum'},{t:'Nothing'}],explain:'Outer false → outer else, inner world never exists.'},{id:'q2',prompt:'The best cure for 5-deep nesting is…',options:[{t:'Flatten with && or early guard returns',ok:true},{t:'Even more nesting'},{t:'Deleting all elses'},{t:'Adding semicolons'}],explain:'Fewer paths means fewer hiding spots for bugs.'},{id:'q3',prompt:'A bare else pairs with…',options:[{t:'The nearest open if',ok:true},{t:'The first if in the method'},{t:'A random if'},{t:'No if at all'}],explain:'Nearest-if binding — brace to make it visible.'},{id:'q4',prompt:'When can you NOT flatten nested ifs with &&?',options:[{t:'When the inner if has its own else branch',ok:true},{t:'When both conditions are true'},{t:'When braces are present'},{t:'Never — always flatten'}],explain:'An inner else needs genuine nesting to hang onto.'}],takeaways:['Nesting = a choice inside a choice.','Flatten with && whenever the inner has no else.','Braces always — dangling else is a trap.','Count paths; too many means restructure.'],recall:'When is nesting the honest tool versus && ?',todo:'Find one nested if in your code and flatten it with &&.',anim:{title:'Russian dolls',steps:[{caption:'Outer doll: weekend? YES — open it.',html:'<div class="pipe"><div class="box"><b>weekend ✓</b> open</div></div>'},{caption:'Inner doll: sunny? No → museum.',html:'<div class="pipe"><div class="box"><b>sunny ❌</b> → museum</div></div>'},{caption:'Flattened form: weekend && sunny?',html:'<div class="pipe"><div class="box">weekend && sunny</div></div>'}]}},
'switch':{intro:'switch is a mail sorter: ONE value glides in, exactly ONE labeled slot accepts it. Cleaner than six else-ifs when a single thing meets many fixed constants.',question:'Why do post offices sort by pincode instead of reading every letter completely?',analogy:'The pincode sorter. It glances at ONE code and slides the letter into exactly one slot; the DEFAULT slot catches unknown codes. Forget break in the old style and the letter slides into the NEXT slot too (fall-through) — chaos.',analogyFail:'Where it breaks: sorters only match exact LABELS (numbers, strings, enums). A “taller than 180 cm” range cannot be a slot — ranges need if-else.',explain:['Classic form: <b>switch (day) { case 1: ...; break; case 2: ...; break; default: ...; }</b>. Each break STOPS the slide; without it, execution falls through into the next case.','Modern <b>arrow form</b> (Java 14+): case 1 -> "Monday"; — no break needed, no fall-through possible. As an EXPRESSION it can also produce a value, like below.','Use switch for fixed choices: days, menu numbers, grade letters, enum values. Use if-else for ranges, booleans, and float comparisons.','Always write <b>default</b>: unknown inputs must land somewhere visible, never vanish silently.'],tech:['switch accepts <b>int, char, String, enums</b> (plus byte/short and wrappers). long, float, double, boolean are REJECTED — the compiler says so.','Arrow switches can be <b>exhaustive expressions</b>: String s = switch (day) { case 1 -> "Mon"; ... default -> "?"; }; — semicolon and all.','String cases use <b>.equals content matching</b> internally (plus null throws NullPointerException — yes, switch on null crashes).'],code:`public class Main {\n  public static void main(String[] args) {\n    int day = 3;\n    String name = switch (day) {\n      case 1 -> "Monday";\n      case 2 -> "Tuesday";\n      case 3 -> "Wednesday";\n      default -> "Unknown day";\n    };\n    System.out.println(name);\n    System.out.println("Day " + day + " done");\n  }\n}`,codeNotes:['day = 3 matches exactly one arrow.','Arrow form needs no break and yields a value.','default catches every other number.'],output:'Wednesday\nDay 3 done',why:'Exact label match on 3; the switch expression hands back "Wednesday"; default never fires.',sim:{kind:'cond',label:'Day sorter: feed it 1–7 and beyond.',fields:[{v:'3'}]},mistakes:[{bad:'Missing break in the old colon style.',why:'Execution FALLS THROUGH into the next case — two slots “accept” one letter.',fix:'Add break; to every case — or switch to the arrow form.'},{bad:'switch (score > 90) or switch (3.5).',why:'Boolean ranges and doubles are not sortable labels — rejected.',fix:'Ranges belong to if-else; doubles to comparisons.'},{bad:'No default, unknown input arrives.',why:'Silence: nothing runs, nothing explains. Debugging nightmare.',fix:'Always add default — even if it just complains loudly.'}],practices:[{title:'Build a menu switch',task:'choice 1 → “Idli”, 2 → “Dosa”, anything else → “Pick 1 or 2”. Arrow style.',hint:'Two arrows plus default.',sol:'String food = switch (choice) { case 1 -> "Idli"; case 2 -> "Dosa"; default -> "Pick 1 or 2"; };'},{title:'Spot the fall-through',task:'Colon style, no breaks: case 1: a(); case 2: b(); — day = 1 runs what?',hint:'Nothing stops the slide.',sol:'BOTH a() and b(). Add break; after each.'}],quiz:[{id:'q1',prompt:'A missing break in colon-style causes…',options:[{t:'Fall-through into the next case',ok:true},{t:'A compiler error, always'},{t:'Nothing at all'},{t:'An infinite loop'}],explain:'Colon cases slide onward unless stopped.'},{id:'q2',prompt:'The arrow form (case 1 -> ...) needs break…',options:[{t:'Never — arrows are single-shot',ok:true},{t:'Always, twice'},{t:'Only on Mondays'},{t:'Only with default'}],explain:'Arrow cases cannot fall through by design.'},{id:'q3',prompt:'switch shines for…',options:[{t:'One value against fixed labels',ok:true},{t:'Ranges like score > 90'},{t:'True/false questions'},{t:'Nothing — never use it'}],explain:'Labels, not ranges: days, menus, letters.'},{id:'q4',prompt:'switch (someString) where someString is null…',options:[{t:'Throws NullPointerException',ok:true},{t:'Matches default safely'},{t:'Matches the first case'},{t:'Skips the switch'}],explain:'Null matches nothing — it detonates. Guard nulls first.'}],takeaways:['One value, many exact labels.','Arrow form kills fall-through; colon form needs break.','Always write default.','Ranges and doubles belong to if-else.'],recall:'When do you reach for switch instead of if-else?',todo:'Write a 3-item food menu with an arrow switch and test all branches.',anim:{title:'Mail sorter',steps:[{caption:'Letter arrives stamped day = 3.',html:'<div class="viz"><div class="varbox"><div class="nm">day</div><div class="vl">3</div></div></div>'},{caption:'It slides into slot 3 only.',html:'<div class="pipe"><div class="box">1</div><div class="box">2</div><div class="box"><b>3 ✓</b></div></div>'},{caption:'Slot 3 hands back “Wednesday”.',html:'<div class="pipe"><div class="box"><b>Wednesday</b></div></div>'}]}},
'for-loops':{intro:'for repeats WITH a counter: a start, a keep-going check, and a step. Perfect when you know (or can compute) how many rounds you need.',question:'How would you instruct “clap 5 times” without writing the word “clap” five times?',analogy:'The washing machine: dial in 5 cycles (start i at 0), check “finished?” before each (i < 5), run the drum and tick the dial (i++). Same three parts, every load, every loop.',analogyFail:'Where it breaks: machines stop by themselves. Code with i-- instead of i++ (or a check that never flips) spins FOREVER — always confirm the check marches toward false.',explain:['Anatomy: <b>for (int i = 0; i < 5; i++)</b> — init runs ONCE, the check runs BEFORE every round, the update runs AFTER every round.','Count from 0 with <b>i < n</b>: it runs exactly n times (0..n−1). The <b><=</b> variant runs n+1 times — the legendary <b>off-by-one</b> error lives here.','The counter is usable inside: print(i), a[i], total += i. Declared inside the for, it DIES at the closing brace — its scope is the loop.','Trace template: a 3-column table of round | i | action. Five minutes of table beats an hour of staring.'],tech:['Execution order per round: <b>check → body → update → check…</b> The update runs even on the final pass (then the check fails and exits).','<b>for (int i = 1; i <= 3; i++)</b> and <b>for (int i = 0; i < 3; i++)</b> both run 3 times — pick the indexing your problem actually needs.','An empty check <b>for (;;)</b> loops forever BY DESIGN (break to escape). An empty update just means the body must advance things itself.'],code:`public class Main {\n  public static void main(String[] args) {\n    for (int i = 1; i <= 3; i++) {\n      System.out.println("Cycle " + i);\n    }\n    System.out.println("Done");\n  }\n}`,codeNotes:['i = 1, check ≤ 3, run body, step.','Rounds for 1, 2, 3 — then i = 4 fails the check.','“Done” prints once, after the loop exits.'],output:'Cycle 1\nCycle 2\nCycle 3\nDone',why:'Three passes, then i = 4 fails ≤ 3, control drops out of the loop to “Done”.',sim:{kind:'loop',label:'Set the cycle count; watch iterations happen.',fields:[{v:'3'}]},mistakes:[{bad:'for (i = 0; i <= 5; i++) while expecting 5 runs.',why:'It runs SIX times (0..5). Inclusive bounds add one.',fix:'Use i < 5 for exactly 5 runs from zero.'},{bad:'Forgetting i++ (or stepping the wrong way).',why:'The check never changes → infinite loop, fan screaming.',fix:'Every loop must advance something the check watches.'},{bad:'Using i AFTER the loop it was declared in.',why:'Its scope ended at the loop’s closing brace.',fix:'Declare the counter before the loop if later code needs it.'}],practices:[{title:'Count it',task:'How many prints? for (int i = 0; i < 4; i++) print(i);',hint:'List them: 0, 1, 2, 3…',sol:'4 prints: 0, 1, 2, 3.'},{title:'Sum 1 to 10',task:'Compute 1+2+…+10 with a for loop and print it.',hint:'total += i inside.',sol:'int t = 0; for (int i = 1; i <= 10; i++) t += i; // 55.'}],quiz:[{id:'q1',prompt:'for (i = 0; i < 5; i++) runs…',options:[{t:'5 times (0–4)',ok:true},{t:'6 times'},{t:'4 times'},{t:'Forever'}],explain:'< n from 0 gives exactly n rounds.'},{id:'q2',prompt:'The update step runs…',options:[{t:'After each body execution',ok:true},{t:'Only before the first check'},{t:'Never'},{t:'At compile time'}],explain:'Body → update → check is the heartbeat.'},{id:'q3',prompt:'i <= n starting from 0 runs…',options:[{t:'n + 1 times',ok:true},{t:'n times'},{t:'Exactly once'},{t:'Zero times'}],explain:'Inclusive upper bounds add one — the off-by-one trap.'},{id:'q4',prompt:'for (;;) with no break does what?',options:[{t:'Loops forever by design',ok:true},{t:'Runs exactly once'},{t:'Skips the body'},{t:'Fails to compile'}],explain:'Empty check = always true. Only break escapes.'}],takeaways:['for = init once; check each round; update each round.','i < n from 0 runs exactly n times.','The update must march the check toward false.','Loop counters die at the closing brace.'],recall:'Recite the three for-parts and when each executes.',todo:'Print your name 5 times with a for loop, numbering each line.',anim:{title:'Washing cycles',steps:[{caption:'Dial in: i = 1.',html:'<div class="viz"><div class="varbox"><div class="nm">i</div><div class="vl">1</div></div></div>'},{caption:'Check 1 ≤ 3 ✓ → wash, tick to 2.',html:'<div class="viz"><div class="varbox"><div class="nm">i</div><div class="vl">2</div></div></div>'},{caption:'Three washes, then 4 ≤ 3 fails → Done.',html:'<div class="pipe"><div class="box">Cycle 1,2,3</div><span class="arr">→</span><div class="box">Done</div></div>'}]}},
'while-loops':{intro:'while repeats WHILE a condition holds — the loop for when you CANNOT know the round count up front: password tries, file lines, network retries.',question:'When exactly do you stop stirring the soup?',analogy:'Taste-and-stir: WHILE too salty → stir and taste again. do-while tastes FIRST (“try the dish before judging”) — it always stirs at least once, even if the soup was perfect.',analogyFail:'Where it breaks: soup eventually balances itself. Code may NEVER balance — if nothing inside moves the condition toward false, you built an infinite loop with extra steps.',explain:['<b>while (cond) { }</b> checks FIRST: zero or more rounds. <b>do { } while (cond);</b> runs once, THEN checks: one or more rounds, note the trailing semicolon.','Something inside MUST advance the condition — a counter, new input, a shrinking file. Frozen conditions spin forever; the stop button (or Ctrl+C) is your escape hatch.','Choose: <b>for</b> = known count; <b>while</b> = unknown rounds, maybe zero (“while files remain”); <b>do-while</b> = must run at least once (“ask the password, repeat while wrong”).','while (true) with an if-break inside is idiomatic for “repeat until event” — menus, servers, game loops. The break IS the condition.'],tech:['do-while’s trailing <b>semicolon is mandatory</b>: do { } while (x); — the only loop that ends with one.','Reading input until a sentinel (“type quit to stop”) is the canonical while job — for-loops cannot do “unknown count” naturally.','Infinite loops are not always bugs: servers intentionally loop forever. The bug is an UNINTENDED one with no exit path.'],code:`public class Main {\n  public static void main(String[] args) {\n    int attempt = 0;\n    int code = 0; // pretend: user keeps typing until 1234\n    while (code != 1234) {\n      attempt++;\n      code = 1234; // first typed guess\n    }\n    System.out.println("Unlocked in " + attempt);\n    // do-while always runs once:\n    int n = 3;\n    do {\n      System.out.println("n = " + n);\n      n--;\n    } while (n > 0);\n  }\n}`,codeNotes:['Check before EVERY round — 0 ≠ 1234 enters once.','The body advances code toward the exit.','do-while prints 3, 2, 1 — guaranteed first run.'],output:'Unlocked in 1\nn = 3\nn = 2\nn = 1',why:'One while round (then 1234 == 1234 exits); the do-while runs its body before its first check, counting 3→1.',sim:{kind:'loop',label:'Unknown rounds: set max tries and trace.',fields:[{v:'4'}]},mistakes:[{bad:'while (true) with no break anywhere.',why:'No exit path — spins until killed.',fix:'Advance the watched value inside, or break on the event.'},{bad:'do-while chosen for a maybe-zero job.',why:'It ALWAYS runs once — “zero files processed” still processes one phantom.',fix:'Maybe-zero needs while; must-run-once needs do-while.'},{bad:'Forgetting attempt++ (or any advance).',why:'Identical state every check → identical answer forever.',fix:'Every loop body must move something the condition watches.'},{bad:'Missing the do-while semicolon.',why:'It is syntactically required — the compiler complains.',fix:'} while (n > 0); — with the semicolon.'}],practices:[{title:'while or do?',task:'“Ask the password until correct — but always ask at least once.” Which loop?',hint:'“At least once” is the password phrase.',sol:'do { ask } while (!correct);'},{title:'Countdown',task:'Print 3, 2, 1, Liftoff using while.',hint:'n = 3; while (n > 0) { ... n--; }',sol:'while (n > 0) { System.out.println(n); n--; } then print Liftoff.'}],quiz:[{id:'q1',prompt:'while checks its condition…',options:[{t:'Before every round (possibly zero rounds)',ok:true},{t:'Only after the loop'},{t:'Never'},{t:'At compile time'}],explain:'Pre-check loop: zero is a legal round count.'},{id:'q2',prompt:'do-while guarantees…',options:[{t:'At least one execution',ok:true},{t:'Possibly zero'},{t:'Exactly two'},{t:'Nothing'}],explain:'Post-check: the body precedes the first question.'},{id:'q3',prompt:'The cure for an accidental infinite loop is…',options:[{t:'Advance the watched value inside the body',ok:true},{t:'Add more comments'},{t:'Rename the counter'},{t:'Delete the braces'}],explain:'Move the condition toward false, every round.'},{id:'q4',prompt:'Which job fits while BEST?',options:[{t:'Read lines until the file ends',ok:true},{t:'Print numbers 1 to 10'},{t:'Run exactly 5 times'},{t:'Add two numbers'}],explain:'Unknown count, maybe zero — while’s home turf.'}],takeaways:['while = unknown rounds, checks first.','do-while always runs once; mind its semicolon.','Every body must advance the condition.','while(true)+break = “repeat until event”.'],recall:'For vs while vs do-while: give the one-line rule for each.',todo:'Write a countdown with while, then rewrite it with do-while, and compare.',anim:{title:'Taste-and-stir',steps:[{caption:'Check: still salty? YES → stir.',html:'<div class="pipe"><div class="box">salty? ✓</div><span class="arr">→</span><div class="box">stir</div></div>'},{caption:'Taste again: balanced? No → stir.',html:'<div class="pipe"><div class="box">balanced? ❌</div><span class="arr">→</span><div class="box">stir</div></div>'},{caption:'Balanced → serve and exit.',html:'<div class="pipe"><div class="box">balanced ✓</div><span class="arr">→</span><div class="box">serve 🍲</div></div>'}]}},
'break-continue':{intro:'break is the emergency exit; continue is skipping one dance move while staying at the party. Both reshape loops without extra nesting — used sparingly, they clarify; abused, they maze.',question:'In a bus queue, what is the difference between LEAVING and letting one person pass?',analogy:'Hopscotch: continue = hop OVER square 4 and keep playing. break = stop the game entirely and go home. Skipping one turn is not quitting the game.',analogyFail:'Where it breaks: skip EVERY square and you finish nothing — and peppering loops with exits hides the real logic. Prefer a clear condition; reserve break/continue for “found it!” and “skip bad data”.',explain:['<b>continue</b> abandons the CURRENT round and jumps to the next check (a for-loop’s update still runs first). <b>break</b> abandons the ENTIRE loop immediately.','Canonical uses: continue skips bad records; break stops a search the moment the target is found (“found it, stop looking”).','Both pair with an if. In a while-loop, continue SKIPS the rest of the body — including your increment if it sits at the bottom. That ordering bug creates infinite loops.','One break on “found” reads clearly; five exits scattered around is maze logic. When exits multiply, restructure with a method return or a flag.'],tech:['<b>Labeled break/continue</b> (outer: ...) can exit nested loops from the inside — rare, but the only clean escape from double loops.','In for-loops continue still executes the <b>update</b>; in while-loops it does NOT re-run anything except the check. Same word, different mechanics.','<b>return</b> exits the whole METHOD (stronger than break); <b>System.exit</b> kills the program (strongest — almost never what you want).'],code:`public class Main {\n  public static void main(String[] args) {\n    for (int i = 1; i <= 5; i++) {\n      if (i == 3) {\n        continue; // skip printing 3, keep looping\n      }\n      if (i == 5) {\n        break; // stop the whole loop before 5\n      }\n      System.out.println(i);\n    }\n    System.out.println("over");\n  }\n}`,codeNotes:['i = 3: the print is jumped over, loop continues.','i = 5: the loop is abandoned on the spot.','Printed: 1, 2, 4 — then “over”.'],output:'1\n2\n4\nover',why:'continue skips only round 3’s print; break at 5 ends everything. The code after the loop always runs.',sim:{kind:'loop',label:'Skip versus stop: trace 5 rounds.',fields:[{v:'5'}]},mistakes:[{bad:'break when you meant skip-one.',why:'break quits the ENTIRE loop — rounds 4 and 5 never happen.',fix:'Skip-one is continue; quit-all is break.'},{bad:'continue in a while-loop with the increment at the bottom.',why:'continue jumps OVER the increment → frozen state → infinite loop.',fix:'Increment BEFORE any continue, or prefer for-loops with skips.'},{bad:'Exits on every other line (“break soup”).',why:'Readers cannot tell the loop’s real shape anymore.',fix:'One break for “found”; otherwise restructure.'}],practices:[{title:'Print the odds',task:'Print odd numbers 1–9 using continue to skip evens.',hint:'if even → continue; else print.',sol:'for (int i = 1; i <= 9; i++) { if (i % 2 == 0) continue; System.out.println(i); }'},{title:'Find and stop',task:'Search 1–10 for the first 7: print it and stop. No extra rounds.',hint:'if (i == 7) { ...; break; }',sol:'for (int i = 1; i <= 10; i++) { if (i == 7) { System.out.println(i); break; } }'}],quiz:[{id:'q1',prompt:'continue does…',options:[{t:'Skips the rest of this round, starts the next',ok:true},{t:'Exits the loop'},{t:'Restarts the program'},{t:'Skips all future rounds'}],explain:'Exactly one round is abandoned.'},{id:'q2',prompt:'break does…',options:[{t:'Exits the loop immediately',ok:true},{t:'Skips one round'},{t:'Pauses for input'},{t:'Nothing'}],explain:'The emergency exit, no rounds after.'},{id:'q3',prompt:'The program above prints…',options:[{t:'1, 2, 4, over',ok:true},{t:'1, 2, 3, 4, 5'},{t:'1, 2, 4, 5, over'},{t:'3, 5'}],explain:'3 skipped, 5 never printed (break first), over always.'},{id:'q4',prompt:'continue inside a while-loop is risky because…',options:[{t:'It can jump over the increment, freezing the loop',ok:true},{t:'It deletes the condition'},{t:'It always breaks instead'},{t:'While forbids continue'}],explain:'Skipped updates = frozen state = infinite spin.'}],takeaways:['continue skips one round; break exits all rounds.','In while, increment BEFORE any continue.','break on “found”; continue on “skip bad data”.','Code after the loop always runs.'],recall:'Give one legitimate use for each — and one abuse for each.',todo:'Print 1–10 while skipping multiples of 3, using continue.',anim:{title:'Hopscotch control',steps:[{caption:'Hop 1, 2 normally.',html:'<div class="pipe"><div class="box">1 ✓</div><div class="box">2 ✓</div></div>'},{caption:'3: continue — skip it, keep playing.',html:'<div class="pipe"><div class="box">3 ⏭️ skip</div><span class="arr">→</span><div class="box">4 ✓</div></div>'},{caption:'5: break — game over, go home.',html:'<div class="pipe"><div class="box">5 🛑 stop</div></div>'}]}},
'nested-loops':{intro:'A loop inside a loop draws tables, grids, and patterns. The outer loop picks the ROW; the inner loop visits every SEAT in that row. Clocks do this (hours × minutes); cinemas do this (rows × seats).',question:'How does one usher seat 5 rows × 8 chairs without memorizing every chair?',analogy:'The cinema usher walks rows 1–5 (outer); at EACH row, they count seats 1–8 (inner, restarting every row). Total seat visits = rows × seats = 40. The inner loop always runs to completion per outer round.',analogyFail:'Where it breaks: ushers tire linearly, but nested work multiplies QUADRATICALLY — 100×100 is 10,000 visits, 10,000×10,000 is a hundred million. Nested loops are the #1 accidental slowness.',explain:['Structure: the <b>outer</b> counter picks the row; the <b>inner</b> counter runs FULLY for each row. Use DIFFERENT variables (r and c) — sharing one corrupts the outer count.','Total inner runs = <b>rows × cols</b>. Always trace a tiny 2×3 before trusting a 100×100.','Grid printing pattern: inner uses <b>print</b> (stay on row), outer ends with <b>println</b> (new row). Swap them and the grid collapses into confetti.','Inner loops restart fresh each outer round — c goes 1..3 for EVERY r. Forgetting the restart is impossible structurally (the inner for re-initializes), which is the beauty of it.'],tech:['Time cost multiplies: O(rows × cols). A 1000×1000 grid is a MILLION inner runs — feel this before writing image or table code.','<b>break</b> exits only its OWN loop; escaping both needs a labeled break or a method return.','Rectangular grids use equal inner counts; <b>jagged</b> grids vary per row — arrays-2d makes this concrete.'],code:`public class Main {\n  public static void main(String[] args) {\n    for (int r = 1; r <= 2; r++) {\n      for (int c = 1; c <= 3; c++) {\n        System.out.print(r + "x" + c + " ");\n      }\n      System.out.println(); // end of row r\n    }\n    System.out.println("seats = 6");\n  }\n}`,codeNotes:['Row 1 prints 1x1 1x2 1x3, then println breaks the row.','Row 2 prints 2x1 2x2 2x3 the same way.','2 × 3 = 6 inner runs over 2 lines.'],output:'1x1 1x2 1x3 \n2x1 2x2 2x3 \nseats = 6',why:'The inner loop completes all 3 seats per outer row; println separates rows; total = 2 × 3.',sim:{kind:'loop',label:'Rows × seats: set the row count.',fields:[{v:'2'}]},mistakes:[{bad:'Reusing i in BOTH loops.',why:'The inner loop overwrites the outer counter — rows miscount, chaos, sometimes infinite.',fix:'Outer r, inner c. Different jobs, different names.'},{bad:'println inside the INNER loop.',why:'Every cell gets its own line — the grid becomes a vertical list.',fix:'print inside, println in the outer after the inner finishes.'},{bad:'Casual 10000×10000 nesting “for a table”.',why:'A hundred million inner runs — the program appears frozen.',fix:'Estimate rows × cols FIRST; break early or rethink.'}],practices:[{title:'Count the visits',task:'3 rows × 4 seats: how many inner-loop runs?',hint:'Multiply.',sol:'12 inner runs.'},{title:'Star triangle',task:'Print this with nested loops: * then ** then ***.',hint:'Row r prints exactly r stars.',sol:'for (int r = 1; r <= 3; r++) { for (int c = 1; c <= r; c++) System.out.print("*"); System.out.println(); }'}],quiz:[{id:'q1',prompt:'2 rows × 3 cols means inner runs…',options:[{t:'6',ok:true},{t:'5'},{t:'4'},{t:'9'}],explain:'Multiply: every row hosts a full inner run.'},{id:'q2',prompt:'Separate counters matter because…',options:[{t:'A shared counter gets corrupted by the inner loop',ok:true},{t:'Java requires the whole alphabet'},{t:'It runs faster'},{t:'Style points only'}],explain:'The inner loop would overwrite the outer’s progress.'},{id:'q3',prompt:'A new grid row starts via…',options:[{t:'println in the outer, after the inner',ok:true},{t:'print in the inner only'},{t:'break, always'},{t:'No newline at all'}],explain:'Row break after all its seats print.'},{id:'q4',prompt:'10 rows × 100 seats costs…',options:[{t:'1000 inner runs',ok:true},{t:'110 runs'},{t:'100 runs'},{t:'10 runs'}],explain:'Multiply. Always estimate before nesting big.'}],takeaways:['Outer = rows, inner = seats per row.','Total work = rows × cols — estimate first.','Different counters; print inside, println per row.','Inner restarts fresh every outer round.'],recall:'How many inner runs for 4×5, and where does the row break go?',todo:'Print a 4×4 multiplication corner (r × c) as a grid.',anim:{title:'Cinema seating',steps:[{caption:'Row 1: seats 1x1, 1x2, 1x3.',html:'<div class="pipe"><div class="box">Row1: 1x1 1x2 1x3</div></div>'},{caption:'Row 2: seats 2x1, 2x2, 2x3.',html:'<div class="pipe"><div class="box">Row2: 2x1 2x2 2x3</div></div>'},{caption:'Total 6 visits = 2 × 3.',html:'<div class="viz"><div class="varbox"><div class="nm">total</div><div class="vl">6</div></div></div>'}]}},
'methods':{intro:'A method is a reusable recipe card: name it once, cook it anywhere. Every repeated block you refuse to extract becomes copy-paste rot that must be fixed in five places.',question:'Why do restaurants print menus instead of explaining each dish table by table?',analogy:'The vending machine. Press B3 (call it), hidden machinery runs fixed steps, a snack drops (maybe with change = return value). You reuse the machine without knowing — or caring — about its insides.',analogyFail:'Where it breaks: vending machines jam on bent coins. Methods jam on bad inputs — garbage in, garbage out. Methods reuse LOGIC, not judgment; validate inputs or document limits.',explain:['<b>Define</b> once: static void greet() { ... }. <b>Call</b> often: greet(); — each call jumps in, runs the body, jumps back to the line after the call.','Calls make code DRY (Don’t Repeat Yourself): fix the card once, every caller improves. Copy-paste makes bugs immortal — the fix lands in 3 copies, the 4th keeps crashing.','<b>void</b> means “no takeaway value” — it DOES something (prints) but RETURNS nothing. Value-returning methods (next lesson) HAND something back.','Methods also NAME ideas: printBill() tells readers what 20 lines do. A well-named method is a comment that cannot rot.'],tech:['A method <b>signature</b> = name + parameter types. Return type is NOT part of it (you cannot overload by return alone).','Each call gets a fresh <b>stack frame</b>: its own parameters and locals, destroyed on return. Recursion is just frames piling up.','<b>static</b> here means “callable without an object” — main is static, so the methods it calls directly must be static too (until objects arrive in Stage 5).'],code:`public class Chef {\n  static void greet() {\n    System.out.println("Welcome!");\n  }\n\n  public static void main(String[] args) {\n    greet();\n    greet();\n    System.out.println("Seated: 2 guests");\n  }\n}`,codeNotes:['greet is defined ONCE as a recipe card.','Called twice — the body runs twice.','Change the card once, both servings improve.'],output:'Welcome!\nWelcome!\nSeated: 2 guests',why:'Each call executes the body fully, returns to the line after the call, and continues. Two calls, two greetings.',sim:{kind:'concat',label:'Call twice, serve twice.',fields:[{v:'Welcome'},{v:'!'}]},mistakes:[{bad:'Defining a method but never calling it.',why:'The card sits in the drawer forever — zero effect, zero error, pure confusion.',fix:'Call it from main (or from another called method).'},{bad:'Copy-pasting a 10-line block three times “for now”.',why:'“For now” is forever: the tripled bug gets fixed twice and survives in copy three.',fix:'Extract a method the SECOND time you paste.'},{bad:'Calling a non-static method from static main.',why:'Instance methods need an object; main has none yet — “non-static method cannot be referenced” greets you.',fix:'Add static (for now — Stage 5 explains the real story).'}],practices:[{title:'Extract it',task:'Two identical receipt-printing blocks sit in main. Extract them.',hint:'Name it printBill(), call it twice.',sol:'static void printBill() { ...the block... } then printBill(); printBill();'},{title:'Call counting',task:'greet() is called 3 times and prints one line each. How many lines total?',hint:'Each call = one full run.',sol:'3 lines.'}],quiz:[{id:'q1',prompt:'The core benefit of methods is…',options:[{t:'Write once, reuse and fix in one place',ok:true},{t:'They run magically faster'},{t:'They delete code'},{t:'They avoid naming things'}],explain:'Single fix point beats copy-paste archaeology.'},{id:'q2',prompt:'A defined-but-never-called method…',options:[{t:'Never runs',ok:true},{t:'Runs once at startup'},{t:'Runs always'},{t:'Causes an error'}],explain:'Definition is potential; only calls execute.'},{id:'q3',prompt:'void means the method…',options:[{t:'Returns nothing (but may DO things)',ok:true},{t:'Is an empty file'},{t:'Takes no parameters'},{t:'Is secret'}],explain:'No takeaway value — printing is doing, not returning.'},{id:'q4',prompt:'Calling a non-static helper from static main gives…',options:[{t:'A compile error about static context',ok:true},{t:'It works fine'},{t:'A runtime crash'},{t:'Two copies running'}],explain:'No object exists in main — static can only touch static (for now).'}],takeaways:['Define once, call often.','Each call jumps in, runs, jumps back.','void = does things, returns nothing.','Name methods after the idea they package.'],recall:'Narrate what happens, step by step, when main calls greet().',todo:'Extract one repeated block from your old code into a method.',anim:{title:'Vending calls',steps:[{caption:'Press B3: call greet().',html:'<div class="pipe"><div class="box">main</div><span class="arr">→</span><div class="box">greet()</div></div>'},{caption:'Hidden machinery runs its steps.',html:'<div class="pipe"><div class="box">println Welcome!</div></div>'},{caption:'Snack drops; control returns to main.',html:'<div class="pipe"><div class="box">greet done</div><span class="arr">→</span><div class="box">main resumes</div></div>'}]}},
'params-return':{intro:'Parameters are order slips going IN; return is the served plate coming OUT. void methods shout “done!”; value methods hand you something to use.',question:'How does ONE kitchen serve “less spicy, extra rice” to table 3 and “extra spicy” to table 7?',analogy:'The service counter. Each slip lists dish + tweaks (parameters: paneer, spice 2). The kitchen returns a plate (return value) or just shouts “done!” (void). Same kitchen, different slips, different plates.',analogyFail:'Where it breaks: kitchens guess missing details (“spice 2-ish?”). Java REFUSES — wrong count or wrong types of arguments is a compile error, not a guess. Precision in, precision out.',explain:['<b>Parameter</b> = the slot in the DEFINITION (int a). <b>Argument</b> = the value at the CALL (4). Types, order, and count must all match.','<b>return value;</b> sends ONE value back to the caller and exits immediately — code after return never runs. The caller should CATCH it: int s = add(4, 5);','<b>void</b> methods return nothing (a bare return; just exits early). Java methods return AT MOST one value — need more? Pack them in an array or object (later).','Arguments are COPIED in (pass-by-value): changing a parameter inside never touches the caller’s variable. For primitives this is absolute; objects share the house (references lesson).'],tech:['<b>Signature</b> matching is compile-time: add(4) or add("x", "y") fails BEFORE running. Read the error — it names the expected types.','An ignored return value compiles fine but wastes work: add(4, 5); alone computes 9 and drops it. Catch or use it.','<b>return;</b> (bare) is legal ONLY in void methods, as an early exit. Value methods must return a value on EVERY path.'],code:`public class Main {\n  static int add(int a, int b) {\n    return a + b; // serve the plate, exit now\n  }\n\n  public static void main(String[] args) {\n    int s = add(4, 5); // argument values 4, 5 fill slots a, b\n    System.out.println(s); // 9\n    System.out.println(add(10, 20)); // 30, used directly\n  }\n}`,codeNotes:['a, b are slots; 4, 5 are the filled-in values.','return sends 9 back and exits add instantly.','s catches the plate; the second call feeds println directly.'],output:'9\n30',why:'First call computes 4 + 5 and stores 9 in s; second call computes 30 inside the print.',sim:{kind:'arith',label:'Order slip in: pick a and b.',fields:[{v:'4'},{o:['+']},{v:'5'}]},mistakes:[{bad:'add(4) — one argument missing.',why:'An unfilled slot: the compiler rejects the call outright.',fix:'Fill every slot: add(4, 5).'},{bad:'add(4, 5); alone, ignoring the 9.',why:'Compiles, computes, drops the plate on the floor.',fix:'Catch it: int s = add(4, 5); — or use it directly.'},{bad:'return; inside an int method.',why:'Value methods must serve the declared type on ALL paths.',fix:'return a + b; — always a value of the right type.'},{bad:'Expecting TWO return values.',why:'Java serves one plate per method, no trays.',fix:'Pack multiples in an array or a small object (later stages).'}],practices:[{title:'Write square',task:'Write int square(int n) returning n * n, then print square(7).',hint:'One return line.',sol:'static int square(int n) { return n * n; } … System.out.println(square(7)); // 49'},{title:'void or value?',task:'printBill() vs getTotal(): which returns something, and how do you tell?',hint:'Does the caller NEED a result?',sol:'getTotal returns (double); printBill is void. Name + need decide.'}],quiz:[{id:'q1',prompt:'Parameter vs argument?',options:[{t:'Slot in the definition vs value at the call',ok:true},{t:'The same thing'},{t:'Return vs void'},{t:'Loop vs if'}],explain:'Slip design versus filled-in slip.'},{id:'q2',prompt:'add(4) when two ints are required…',options:[{t:'Fails to compile',ok:true},{t:'Runs as 9'},{t:'Uses 0 for b'},{t:'Asks the user'}],explain:'Count and types must match — checked before running.'},{id:'q3',prompt:'return inside a method does…',options:[{t:'Sends a value back AND exits immediately',ok:true},{t:'Always prints'},{t:'Loops again'},{t:'Deletes the method'}],explain:'One plate served, kitchen visit over.'},{id:'q4',prompt:'Changing a parameter inside the method affects the caller’s variable…',options:[{t:'Never (arguments are copied in)',ok:true},{t:'Always'},{t:'Only for ints'},{t:'Only on Fridays'}],explain:'Pass-by-value: the method gets a private copy.'}],takeaways:['Parameters in, return out — matched exactly.','Catch the return value or lose the work.','One return value max; bare return only in void.','Arguments are copied; parameters are private.'],recall:'Can a Java method return two values directly? How do pros pack more?',todo:'Write a bill-total method (double in, double out) and test it twice.',anim:{title:'Order slip in, plate out',steps:[{caption:'Slip arrives: add(4, 5).',html:'<div class="pipe"><div class="box">a=4, b=5 (copies)</div></div>'},{caption:'Kitchen computes 4 + 5.',html:'<div class="pipe"><div class="box">compute 9</div></div>'},{caption:'Plate 9 served back to s.',html:'<div class="pipe"><div class="box"><b>return 9</b></div><span class="arr">→</span><div class="box">s = 9</div></div>'}]}},
'scope':{intro:'Scope = where a variable is visible AND alive. Braces are hotel rooms: what happens in the room mostly stays in the room — and checkout (the closing brace) deletes everything inside.',question:'Why can’t the hotel lobby hear your shower singing?',analogy:'Hotel rooms. The lobby whiteboard (outer variable) is visible from every room on the floor; a room’s diary (inner variable) dies at checkout. Inner rooms see outward; the lobby cannot see inward.',analogyFail:'Where it breaks: hotels share Wi-Fi and gossip. Code rooms share NOTHING unless values are passed as parameters or returned — no snooping across braces, ever.',explain:['<b>Block scope</b>: a variable declared inside { } lives ONLY there. Loop counters, if-block temps — all checked out at the closing brace.','<b>Shadowing</b>: declaring an inner variable with an outer’s name HIDES the outer one inside. Legal, confusing, avoid — rename instead.','<b>Lifetime</b>: born at declaration, destroyed at }. Using a variable after its brace is a compile error, not a weird value — the compiler protects you.','Rule of thumb: declare each variable in the SMALLEST brace-block that needs it, as LATE as possible. Wide variables invite distant bugs.'],tech:['Java is <b>lexically scoped</b>: visibility is decided by brace NESTING in the source, never by who-called-whom at runtime.','A <b>for-loop header variable</b> (for (int i...)) is scoped TO the loop — the classic “cannot find symbol: i” after the loop.','You CANNOT redeclare a name in the same block (int x twice = error), but a nested block MAY shadow method parameters and fields — don’t.'],code:`public class Main {\n  public static void main(String[] args) {\n    int hall = 1; // lobby: visible everywhere below\n    if (true) {\n      int room = 2; // room: dies at the closing brace\n      System.out.println(hall + room); // 3: inner sees outer\n    }\n    System.out.println(hall); // 1: outer never saw room\n    // System.out.println(room); // COMPILE ERROR: checked out\n  }\n}`,codeNotes:['hall is visible inside the if — outward visibility works.','room dies at its }; the commented line would not compile.','Uncomment it yourself and read the exact error.'],output:'3\n1',why:'Inner sees outer (3 = 1 + 2); outer cannot see inner, so only hall prints after.',sim:{kind:'arith',label:'Rooms combine: hall + room.',fields:[{v:'1'},{o:['+']},{v:'2'}]},mistakes:[{bad:'Using the loop counter after its loop.',why:'Checked out at } — “cannot find symbol” is the compiler telling you so.',fix:'Declare the counter BEFORE the loop if later code needs it.'},{bad:'Shadowing: int x outside, int x inside.',why:'Two boxes, one name — every reader (including you) will confuse them.',fix:'Rename the inner one. Different jobs, different names.'},{bad:'Declaring everything at the top “to be safe”.',why:'Giant visibility = bugs can strike from anywhere; readers track the whole method.',fix:'Declare close to first use, in the smallest block.'}],practices:[{title:'Alive or not?',task:'{ int q = 5; } System.out.println(q); — compiles?',hint:'Where did q check out?',sol:'No — q died at }. Move the print inside, or declare q outside.'},{title:'Fix the shadow',task:'Fix: int x = 1; { int x = 2; } (same block family).',hint:'Actually this FAILS to compile — same method, nested block. Rename.',sol:'int x = 1; { int y = 2; } — shadowing locals like this is rejected; rename.'}],quiz:[{id:'q1',prompt:'A room variable after its } is…',options:[{t:'Gone — using it is a compile error',ok:true},{t:'Still fully usable'},{t:'Moved to the lobby'},{t:'Doubled'}],explain:'Lifetime ends at the brace. The compiler enforces it.'},{id:'q2',prompt:'An inner block can see…',options:[{t:'Outer (enclosing) variables',ok:true},{t:'Nothing at all'},{t:'Future code below'},{t:'Other files’ locals'}],explain:'Visibility flows inward, never outward.'},{id:'q3',prompt:'Shadowing is…',options:[{t:'One name hiding another — rename to avoid it',ok:true},{t:'Required in every method'},{t:'A kind of loop'},{t:'A data type'}],explain:'Legal but confusing — clarity wins.'},{id:'q4',prompt:'A for-loop’s int i after the loop…',options:[{t:'Does not exist (scoped to the loop)',ok:true},{t:'Holds the last value'},{t:'Holds zero'},{t:'Holds the count'}],explain:'Header variables die with their loop.'}],takeaways:['Braces bound both visibility and life.','Inner sees outer; outer never sees inner.','Smallest block, latest declaration wins.','Shadowed names are a readability debt.'],recall:'Where should a variable used ONLY inside a loop be declared — and why?',todo:'Shrink one over-wide variable’s scope in your old code.',anim:{title:'Hotel checkout',steps:[{caption:'Lobby board hall = 1, floor sees it.',html:'<div class="viz"><div class="varbox"><div class="nm">hall</div><div class="vl">1</div></div></div>'},{caption:'Room 2 opens: sees hall AND room.',html:'<div class="viz"><div class="varbox"><div class="nm">room</div><div class="vl">2</div></div></div>'},{caption:'Checkout: room deleted, hall stays.',html:'<div class="pipe"><div class="box">room ❌ gone</div><div class="box">hall ✓ stays</div></div>'}]}},
'debugging':{intro:'Bugs are not shame — they are the job. Professionals just find them FASTER: read the error, reproduce on demand, narrow the suspects, change ONE thing, re-test. This lesson is that entire workflow.',question:'If the toast burns, do you rebuild the whole kitchen?',analogy:'The detective kit. Victim = the error line. Witnesses = print statements showing values. Alibis = the exact inputs. And the golden rule: investigate the FIRST error — later ones are usually gossip caused by it.',analogyFail:'Where it breaks: detectives sometimes guess motives and get lucky. Debuggers who guess (“maybe THIS fixes it?”) create NEW bugs. Change one thing, re-run, observe — science, not horoscopes.',explain:['Four species: <b>syntax</b> (red ink, zero building), <b>compile-time type</b> (wrong types), <b>runtime exception</b> (builds, then crashes mid-run), <b>logic</b> (runs fine, answers wrong — the dangerous one).','A <b>stack trace</b> reads top-down: exception name, then YOUR file:line. “ArrayIndexOutOfBoundsException at Main.java:7” means GO TO LINE 7 — the answer is an address, not a riddle.','The workflow: <b>reproduce</b> (same input → same failure) → <b>print suspects</b> (show values at each step) → <b>bisect</b> (disable half the code; bug in the guilty half?) → <b>fix the FIRST cause</b> → re-run everything.','Logic bugs need ORACLES: known input→output pairs. 2 + 2 must be 4; if your calculator says 5, the oracle convicts the code — no red ink needed.'],tech:['<b>javac</b> errors show file:line:column — the CARET points at the token, though the real mistake often sits slightly BEFORE it (a missing bracket above).','Runtime traces list calls newest-first: YOUR line is usually the first line naming YOUR file; library frames below are context.','<b>System.out.println debugging</b> (“caveman debugging”) is legitimate and fast; step-debuggers (IDE breakpoints) are the power tool for later.'],code:`public class Main {\n  public static void main(String[] args) {\n    int[] m = {80, 90};\n    System.out.println(m[0]); // 80: fine\n    // System.out.println(m[5]); // INDEX 5 on length 2: crash!\n    int total = m[0] + m[1];\n    System.out.println("total = " + total); // 170?\n  }\n}`,codeNotes:['Valid index prints 80 — the control case.','The commented line WOULD crash: doors 0–1 only.','Logic check: is 170 the expected total? Verify!'],output:'80\ntotal = 170',why:'In-bounds works; the killer line stays commented. The total passes its oracle (80 + 90 = 170).',sim:{kind:'array',label:'Knock on doors: 0–1 open, 5 crashes.',fields:[{v:'1'}]},mistakes:[{bad:'Fixing the LAST of 20 errors first.',why:'Errors cascade: #1 breaks parsing, #2–20 are its echoes.',fix:'Fix #1 only. Rebuild. Repeat.'},{bad:'Changing five things at once “to be sure”.',why:'Now NOTHING is the cause — you cannot tell which change mattered.',fix:'One change, one re-run, one observation.'},{bad:'“No red ink, so it must be right.”',why:'Logic bugs wear no red. Wrong answers compile beautifully.',fix:'Test every unit against a hand-computed oracle.'},{bad:'Reading the whole trace bottom-up.',why:'Bottom frames are library internals; YOUR bug address sits near the top.',fix:'Find the first line naming YOUR file. Go there.'}],practices:[{title:'Read the address',task:'“ArrayIndexOutOfBoundsException at Main.java:7” — where exactly is the crime scene?',hint:'File, colon, line.',sol:'Main.java, line 7 — open it; the bad index is there.'},{title:'Bisect it',task:'A 100-line program prints a wrong total. What is your FIRST move?',hint:'Disable half, observe.',sol:'Comment out half. Wrongness stays → bug in the live half; vanishes → bug in the dead half. Repeat.'}],quiz:[{id:'q1',prompt:'Which bug kind runs fine but answers wrong?',options:[{t:'Logic error',ok:true},{t:'Syntax error'},{t:'Missing file'},{t:'No such kind exists'}],explain:'Silent wrongness — the kind oracles exist to catch.'},{id:'q2',prompt:'Twenty errors appear. Start…',options:[{t:'At the FIRST error',ok:true},{t:'At the last error'},{t:'At a random one'},{t:'By deleting everything'}],explain:'Error #1 causes the cascade; the rest are echoes.'},{id:'q3',prompt:'m[5] on a length-2 array gives…',options:[{t:'ArrayIndexOutOfBoundsException at that line',ok:true},{t:'0, quietly'},{t:'5'},{t:'It compiles away'}],explain:'Bounds are enforced at runtime, loudly.'},{id:'q4',prompt:'In a stack trace, YOUR bug’s address is…',options:[{t:'The first line naming YOUR file',ok:true},{t:'The very bottom line'},{t:'The longest line'},{t:'Never shown'}],explain:'Newest call first; your frame tops the ones you own.'}],takeaways:['Four species: syntax, type, runtime, logic.','Traces give file:line addresses — go there.','First error first; one change per test.','Oracles (known answers) catch logic bugs.'],recall:'Recite the 5-step debugging workflow without looking.',todo:'Start a bug diary: error text → cause → fix. Three entries this week.',anim:{title:'Detective workflow',steps:[{caption:'Victim found: error names line 7.',html:'<div class="pipe"><div class="box"><b>Main.java:7</b><br>out of bounds!</div></div>'},{caption:'Witnesses: prints reveal the index.',html:'<div class="pipe"><div class="box">print i → 5 ⚠️ (max 1)</div></div>'},{caption:'Fix once, re-run all, case closed. ✓',html:'<div class="pipe"><div class="box">guard index → pass ✓</div></div>'}]}},
'arrays':{intro:'An egg tray holds exactly 12 eggs — identical slots, numbered positions, zero growth. Arrays are Java’s egg trays: many values, ONE type, numbered from ZERO, fixed at birth.',question:'Why not carry 30 eggs home in your bare hands?',analogy:'The egg tray. Twelve fixed slots, slot 0 first. Need thirteen eggs? Buy a bigger tray (new array) or switch to an expandable basket (ArrayList, Stage 6) — the tray itself NEVER stretches.',analogyFail:'Where it breaks: eggs vary; array slots CANNOT. One tray, one type — ints and Strings never share. And trays don’t wash themselves: unused slots hold defaults (0, false, null), not “empty”.',explain:['Create sized: <b>int[] a = new int[3];</b> (three zeros) or pre-filled: <b>int[] a = {10, 20, 30};</b> Either way the <b>length is FIXED forever</b>: a.length.','Slots are numbered <b>0 to length−1</b>. Read with a[i], write with a[i] = v. The box brackets mean “slot number”.','Arrays are OBJECTS: the variable holds a reference to the tray (heap!), not the eggs. Copying the variable shares the tray — the references lesson strikes again.','Declaration trivia that matters: <b>int[] a</b> (preferred) vs int a[] (legal relic) — same thing. And a.length has NO brackets: it is a field, not a method.'],tech:['<b>new int[3]</b> zero-fills: {0,0,0}. Object arrays null-fill: new String[3] is {null,null,null} — touching [0].length() crashes.','<b>Arrays are covariant but checked</b>: String[] IS an Object[], yet storing an Integer throws ArrayStoreException at runtime. (Generics later fix this properly.)','<b>int[] a = null;</b> is a slip to nowhere — a[0] on it is NullPointerException, not “empty array”.'],code:`public class Main {\n  public static void main(String[] args) {\n    int[] eggs = {10, 20, 30};\n    System.out.println("slots = " + eggs.length);\n    System.out.println("first = " + eggs[0]);\n    eggs[1] = 99; // swap slot 1\n    System.out.println("swapped = " + eggs[1]);\n    System.out.println("last = " + eggs[eggs.length - 1]);\n  }\n}`,codeNotes:['length is 3 — born that way, stays that way.','Slot 0 reads 10; slot 1 gets overwritten with 99.','Last slot is ALWAYS index length − 1.'],output:'slots = 3\nfirst = 10\nswapped = 99\nlast = 30',why:'A fixed tray of 3: slots read and written by number; the length never moves.',sim:{kind:'array',label:'Open slots 0–2; knock on 5 and watch.',fields:[{v:'0'}]},mistakes:[{bad:'int[] a = new int[-2];',why:'A negative tray is nonsense — NegativeArraySizeException at runtime.',fix:'Sizes are zero or positive. Always.'},{bad:'Expecting the tray to grow: a[3] = 7 on length 3.',why:'Fixed means fixed — slot 3 does not exist and never will.',fix:'Build a bigger array (copy over) or use ArrayList.'},{bad:'int[] a; then a[0] immediately.',why:'Declared but never built — a is null, and null has no slots.',fix:'a = new int[3]; FIRST, then touch slots.'},{bad:'int a[] = new int[3]; confusion about style.',why:'Legal but backwards-looking; modern code writes the brackets with the TYPE.',fix:'int[] a — brackets on the type, always.'}],practices:[{title:'Last slot math',task:'An array has length 5. What is its last valid index?',hint:'Zero-based: subtract one.',sol:'4. First 0, last length − 1.'},{title:'Defaults drill',task:'new int[3] and new String[2] — exact contents?',hint:'Numbers zero-fill; objects null-fill.',sol:'[0, 0, 0] and [null, null].'}],quiz:[{id:'q1',prompt:'int[3] has valid indexes…',options:[{t:'0, 1, 2',ok:true},{t:'1, 2, 3'},{t:'0, 1, 2, 3'},{t:'Any integer'}],explain:'Zero-based up to length − 1.'},{id:'q2',prompt:'Java arrays are…',options:[{t:'One type, fixed length',ok:true},{t:'Mixed types, free growth'},{t:'Always empty'},{t:'Type-changing'}],explain:'One type per tray, slots fixed at birth.'},{id:'q3',prompt:'new String[2] contains…',options:[{t:'null, null',ok:true},{t:'"", ""'},{t:'Nothing — it is null itself'},{t:'0, 0'}],explain:'Object slots null-fill. Touching them blindly crashes.'},{id:'q4',prompt:'eggs.length uses no brackets because…',options:[{t:'It is a field, not a method call',ok:true},{t:'Arrays are special-cased magic'},{t:'It is a method anyway'},{t:'Brackets are optional'}],explain:'length is data ON the array; length() (Strings) is work DONE.'}],takeaways:['One type, numbered from 0, fixed at birth.','length counts slots; last index is length − 1.','Arrays are heap objects; variables are slips.','new zero/null-fills every slot.'],recall:'How do you compute the last index, and why is length bracket-free?',todo:'Store 5 friends’ ages in an array; print first and last with labels.',anim:{title:'Egg tray mechanics',steps:[{caption:'Fresh tray of 3: zeros inside.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">0</div></div><div class="memcell"><div class="idx">1</div><div class="val">0</div></div><div class="memcell"><div class="idx">2</div><div class="val">0</div></div></div>'},{caption:'Fill: 10, 20, 30.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">10</div></div><div class="memcell"><div class="idx">1</div><div class="val">20</div></div><div class="memcell"><div class="idx">2</div><div class="val">30</div></div></div>'},{caption:'eggs[1] = 99 swaps slot 1 only.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">10</div></div><div class="memcell"><div class="idx">1</div><div class="val">99 ✨</div></div><div class="memcell"><div class="idx">2</div><div class="val">30</div></div></div>'}]}},
'indexing-bounds':{intro:'Index 0 is first, length−1 is last, and anything else is a door that does not exist. Java guards every knock — wrong doors don’t return garbage, they detonate loudly.',question:'Why do some countries skip “floor 0” while programmers worship it?',analogy:'The hotel with floors 0–4 (five floors). The top floor is floors − 1 = 4. Knock on floor 9 and security (ArrayIndexOutOfBoundsException) escorts you out — no fake rooms, no polite lies.',analogyFail:'Where it breaks: hotels sometimes forgive trespassers. Java NEVER forgives out-of-bounds: instant exception, exact line number, every time. The strictness is the feature.',explain:['First slot = <b>0</b>, last slot = <b>length − 1</b>. The universal safe loop is <b>for (i = 0; i < a.length; i++)</b> — strict <, never <=.','<b>a[a.length]</b> ALWAYS crashes: the highest door number is one less than the count. Off-by-one here is the most common array bug in existence.','Arrays use <b>a.length</b> (a FIELD, no brackets); Strings use <b>s.length()</b> (a METHOD). Mixing them up is a rite of passage — now you are vaccinated.','Bounds are checked at RUNTIME on every access: safety costs a nanosecond and saves days of “why is my data weird” (other languages return garbage instead).'],tech:['The exception names the crime: <b>ArrayIndexOutOfBoundsException: Index 3 out of bounds for length 3</b> — read it, go to the line, fix the index.','Negative indexes are equally illegal: a[-1] crashes. (Python-style wrap-around does NOT exist in Java.)','<b>Enhanced for-loops</b> (for (int v : a)) cannot go out of bounds BY CONSTRUCTION — one reason pros prefer them for reading.'],code:`public class Main {\n  public static void main(String[] args) {\n    int[] a = {5, 6, 7};\n    System.out.println("first = " + a[0]);\n    System.out.println("last = " + a[a.length - 1]);\n    System.out.println("doors = " + a.length);\n    // System.out.println(a[3]); // door 3 missing: CRASH\n  }\n}`,codeNotes:['First door is 0, always.','Last door is length − 1, always.','Door 3 on a 3-long array does not exist.'],output:'first = 5\nlast = 7\ndoors = 3',why:'Length 3 means doors 0, 1, 2 exist. Door 3 stays commented — uncomment it to meet the exception personally.',sim:{kind:'array',label:'Knock on doors 0–5 and feel the rules.',fields:[{v:'3'}]},mistakes:[{bad:'for (i = 0; i <= a.length; i++)',why:'Visits one ghost door past the end — crashes on the final round, every time.',fix:'Strict less-than: i < a.length. Tattoo it.'},{bad:'a.length() with brackets on an array.',why:'Arrays expose length as DATA; only Strings (and friends) compute length().',fix:'a.length for arrays, s.length() for strings.'},{bad:'Assuming the last index equals the length.',why:'The eternal off-by-one: 3 doors means top door 2.',fix:'Last = length − 1. Say it aloud.'},{bad:'Catching the exception to “handle” a wrong index.',why:'Masks the bug — the index math is still wrong underneath.',fix:'Fix the INDEX, don’t sedate the symptom.'}],practices:[{title:'Last of seven',task:'An array has length 7. Last valid index?',hint:'Minus one.',sol:'6.'},{title:'Fix the tour',task:'Fix this to visit exactly every slot: for (int i = 0; i <= a.length; i++)',hint:'One character changes.',sol:'for (int i = 0; i < a.length; i++) — <= becomes <.'}],quiz:[{id:'q1',prompt:'A length-4 array’s last index is…',options:[{t:'3',ok:true},{t:'4'},{t:'0'},{t:'-1'}],explain:'length − 1, always and forever.'},{id:'q2',prompt:'a[4] on a length-4 array…',options:[{t:'Throws ArrayIndexOutOfBoundsException',ok:true},{t:'Returns 0 quietly'},{t:'Returns null'},{t:'Compiles the array away'}],explain:'Doors 0–3 exist. Door 4 is wall.'},{id:'q3',prompt:'Array length is read via…',options:[{t:'a.length (field, no brackets)',ok:true},{t:'a.length()'},{t:'a.size()'},{t:'len(a)'}],explain:'Data on arrays; work on Strings.'},{id:'q4',prompt:'a[-1] in Java…',options:[{t:'Crashes like any out-of-bounds',ok:true},{t:'Reads the last element'},{t:'Reads the first element'},{t:'Returns null'}],explain:'No Python-style wrap-around. Negative = illegal.'}],takeaways:['0 first, length − 1 last — no exceptions.','Tour with strict < length.','Outside the doors → loud exception, exact line.','length vs length(): field vs method.'],recall:'A length-n array has how many doors, numbered how?',todo:'Print the first, middle, and last elements of an array — safely.',anim:{title:'Hotel doors',steps:[{caption:'Five floors? Doors 0–4 (shown: 3).',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">5</div></div><div class="memcell"><div class="idx">1</div><div class="val">6</div></div><div class="memcell"><div class="idx">2</div><div class="val">7</div></div></div>'},{caption:'Knock 2 → opens (7). ✓',html:'<div class="pipe"><div class="box">a[2] → 7 ✓</div></div>'},{caption:'Knock 3 → security! 🚨',html:'<div class="pipe"><div class="box">a[3] → 💥 out of bounds</div></div>'}]}},
'traverse-arrays':{intro:'Visiting every slot in order — to print, sum, or upgrade — is called traversing. Loops are the tour bus, and Java runs two models: the counting bus (needs the seat NUMBER) and the sightseeing bus (just greets each passenger).',question:'How do you water 20 plants in a row without missing one or drowning one twice?',analogy:'The tour bus with numbered seats. The classic for counts seats (needs the INDEX to repaint them); for-each just greets each passenger (no index, no repainting). To CHANGE seats, you need the counting bus — photos can’t move furniture.',analogyFail:'Where it breaks: for-each hands you a PHOTO of each primitive, not the seat. Writing on the photo (v += 5) changes nothing in the tray — the classic “why didn’t my array change?!” mystery.',explain:['<b>Classic for</b> when you need the index or must WRITE: a[i] = ..., a[i] *= 2. The index is the address; without it you cannot deliver changes.','<b>for (int v : a)</b> (enhanced for-each) when you only READ: sum += v, print(v). Simpler, bounds-safe by construction, preferred for reading.','v is a COPY for primitives (editing it is scribbling on a photo) — but for OBJECTS it copies the slip, so v.setX() WOULD reach the shared house. Same syntax, different physics!','Accumulator pattern: initialize BEFORE the loop (sum = 0), update INSIDE, use AFTER. Forgetting the init is the #1 traversal bug.'],tech:['for-each desugars to an <b>index loop</b> (arrays) or an <b>Iterator</b> (collections) — same work, less typing, zero off-by-one surface.','You CANNOT get the current index from for-each; you CANNOT remove collection elements in one (use removeIf/iterator — Stage 6).','<b>a[i] += 5</b> reads, adds, and writes back in one line — the standard in-place upgrade idiom.'],code:`public class Main {\n  public static void main(String[] args) {\n    int[] m = {80, 90, 70};\n    int sum = 0;\n    for (int v : m) {\n      sum += v; // sightseeing: read-only tour\n    }\n    System.out.println("sum = " + sum);\n    for (int i = 0; i < m.length; i++) {\n      m[i] += 5; // counting bus: repaint every seat\n    }\n    System.out.println("first now = " + m[0]);\n  }\n}`,codeNotes:['for-each reads all three into sum = 240.','The index loop writes +5 into every slot.','First slot: 80 → 85.'],output:'sum = 240\nfirst now = 85',why:'The read tour sums without touching; the write tour upgrades each slot in place.',sim:{kind:'loop',label:'Tour 3 seats and watch the sum grow.',fields:[{v:'3'}]},mistakes:[{bad:'for (int v : m) v += 5; on an int array.',why:'v is a PHOTO — the tray never changes, the loop “works” and achieves zero.',fix:'Write tours need addresses: for (i...) m[i] += 5;.'},{bad:'for (i = 0; i <= m.length; i++) on tour.',why:'The ghost-seat finale crashes the whole trip.',fix:'Strict <: i < m.length.'},{bad:'int sum; then sum += v (no init).',why:'Locals have no defaults — “variable might not have been initialized”.',fix:'int sum = 0; BEFORE the loop.'}],practices:[{title:'Average it',task:'Compute the average of {80, 90, 70} as a double.',hint:'Sum, then divide by length as double.',sol:'240 / 3.0 = 80.0 — the 3.0 forces double math.'},{title:'Double every slot',task:'Double each element IN the array with an index loop.',hint:'m[i] *= 2.',sol:'for (int i = 0; i < m.length; i++) m[i] *= 2;'}],quiz:[{id:'q1',prompt:'To WRITE array slots you need…',options:[{t:'The classic index loop',ok:true},{t:'for-each on primitives'},{t:'No loop at all'},{t:'A switch'}],explain:'Writing needs the address; photos can’t be delivered to.'},{id:'q2',prompt:'for-each variable v over int[] is…',options:[{t:'A copy — edits to it are lost',ok:true},{t:'The real slot itself'},{t:'The index number'},{t:'The array length'}],explain:'Photo semantics for primitives.'},{id:'q3',prompt:'The program’s sum is…',options:[{t:'240',ok:true},{t:'170'},{t:'245'},{t:'0'}],explain:'80 + 90 + 70, toured and tallied.'},{id:'q4',prompt:'for (int v : objects) { v.setX(1); } — affects the array’s objects?',options:[{t:'Yes — v copies the slip, reaching the shared house',ok:true},{t:'No — always a photo'},{t:'It crashes'},{t:'It deletes them'}],explain:'Object for-each copies REFERENCES. Methods called on them reach home.'}],takeaways:['Read with for-each; write with index loops.','Initialize accumulators BEFORE the loop.','Strict < length on every tour.','Photos vs slips: know which v is.'],recall:'When MUST you use the index loop? Give two reasons.',todo:'Sum and average your 5-ages array both ways (for + for-each).',anim:{title:'Two tour buses',steps:[{caption:'Stop 0: greet 80, sum 80.',html:'<div class="viz"><div class="memcell"><div class="idx">0</div><div class="val">80 ✓</div></div><div class="memcell"><div class="idx">1</div><div class="val">90</div></div><div class="memcell"><div class="idx">2</div><div class="val">70</div></div></div>'},{caption:'Stop 1: greet 90, sum 170.',html:'<div class="viz"><div class="memcell"><div class="idx">1</div><div class="val">90 ✓</div></div></div>'},{caption:'Stop 2: greet 70, sum 240. Tour complete.',html:'<div class="viz"><div class="varbox"><div class="nm">sum</div><div class="vl">240</div></div></div>'}]}},
'arrays-2d':{intro:'A 2D array is a grid: rows of rows. Cinema seats, chessboards, mark tables, pixels — anything with [row][seat] addressing lives here.',question:'How do you find “block C, seat 4” without inspecting every chair in the cinema?',analogy:'The cinema. Block C, chair 4 = grid[2][3] (zero-based backstage). Some balconies are shorter — each row is its OWN array, so rows may legally differ in length (jagged).',analogyFail:'Where it breaks: cinemas label from 1 and forgive mistakes. Code labels from 0 and punishes: grid[0][0] is the true first seat, and grid[5][0] on 2 rows detonates.',explain:['Declare: <b>int[][] g = new int[2][3];</b> (2 rows × 3 seats, zero-filled) or pre-filled <b>{{1,0,1},{0,1,1}}</b>. Read/write one seat: <b>g[r][c]</b>.','<b>g.length</b> = row count; <b>g[r].length</b> = seats in row r — PER ROW, because jagged rows exist. Never assume all rows match.','Fill/visit with NESTED loops: outer walks rows, inner walks that row’s seats. Print rows with the print/println pattern from nested-loops.','Memory truth: there is no true “rectangle” — a 2D array is an array OF array-references. g[0] and g[1] are independent trays that happen to sit in one holder.'],tech:['<b>Jagged arrays</b> are normal: new int[3][] then g[0] = new int[2]; g[1] = new int[5]; — each row sized separately.','<b>g.length</b> rows vs <b>g[r].length</b> cols-in-that-row: using g[0].length for every row breaks on jagged grids.','Row swap is O(1): int[] t = g[0]; g[0] = g[1]; g[1] = t; — slips trade places, seats never move.'],code:`public class Main {\n  public static void main(String[] args) {\n    int[][] seats = {{1, 0, 1}, {0, 1, 1}}; // 1 = free\n    System.out.println("seat[0][1] = " + seats[0][1]);\n    System.out.println("size = " + seats.length + "x" + seats[0].length);\n    int free = 0;\n    for (int r = 0; r < seats.length; r++) {\n      for (int c = 0; c < seats[r].length; c++) {\n        if (seats[r][c] == 1) free++;\n      }\n    }\n    System.out.println("free = " + free);\n  }\n}`,codeNotes:['Row 0, seat 1 reads 0 (taken).','Size: 2 rows × 3 seats.','Nested tour counts the 1s: four free.'],output:'seat[0][1] = 0\nsize = 2x3\nfree = 4',why:'Two-number addressing reads one seat; per-row lengths drive the nested count of free seats.',sim:{kind:'array',label:'Pick a seat number to inspect.',fields:[{v:'1'}]},mistakes:[{bad:'seats[3][0] on a 2-row grid.',why:'Row 3 was never built — same detonation, two dimensions.',fix:'Rows 0..length−1; check seats.length first.'},{bad:'Using seats[0].length for EVERY row.',why:'Works until a jagged row arrives — then miscounts or crashes.',fix:'Inner bound is seats[r].length, per current row.'},{bad:'One flat loop “visiting seats”.',why:'A single loop visits ROWS (each an array), not seats.',fix:'Nest: outer rows, inner seats[r].length.'}],practices:[{title:'First seat',task:'What is seats[0][0] in the program? Which corner is it?',hint:'Row 0, seat 0.',sol:'1 — the top-left corner.'},{title:'Count the taken',task:'Count 0s (taken seats) with nested loops.',hint:'Mirror the free-count with == 0.',sol:'2 taken seats.'}],quiz:[{id:'q1',prompt:'seats[0][1] addresses…',options:[{t:'Row 0, seat 1',ok:true},{t:'Row 1, seat 0'},{t:'Seat 1 total'},{t:'Row 1, seat 1'}],explain:'[row][col], both zero-based.'},{id:'q2',prompt:'Row count is read via…',options:[{t:'g.length',ok:true},{t:'g[0].length'},{t:'g.size'},{t:'len(g)'}],explain:'Outer length = number of rows.'},{id:'q3',prompt:'Filling every seat needs…',options:[{t:'Nested loops (rows × seats)',ok:true},{t:'A single if'},{t:'A switch'},{t:'No loops'}],explain:'Two dimensions demand two loops.'},{id:'q4',prompt:'A 2D Java array really is…',options:[{t:'An array of array-references (rows can differ)',ok:true},{t:'One solid rectangle in memory'},{t:'A list of Strings'},{t:'A single row'}],explain:'Holder of independent row-trays — hence jagged.'}],takeaways:['Grid = array of row-arrays.','[row][col], both zero-based.','Rows: g.length; seats: g[r].length per row.','Nested loops tour; rows may be jagged.'],recall:'How do you count ALL seats, and why per-row length?',todo:'Model a 3×3 tic-tac-toe board and print it as a grid.',anim:{title:'Cinema grid mechanics',steps:[{caption:'Two blocks × three chairs each.',html:'<div class="viz"><div class="memcell"><div class="idx">0,0</div><div class="val">1</div></div><div class="memcell"><div class="idx">0,1</div><div class="val">0</div></div><div class="memcell"><div class="idx">0,2</div><div class="val">1</div></div></div>'},{caption:'Seat [0][1] reads 0 (taken).',html:'<div class="pipe"><div class="box">row 0, seat 1 → 0</div></div>'},{caption:'Row 1 next: 0, 1, 1.',html:'<div class="viz"><div class="memcell"><div class="idx">1,0</div><div class="val">0</div></div><div class="memcell"><div class="idx">1,1</div><div class="val">1</div></div><div class="memcell"><div class="idx">1,2</div><div class="val">1</div></div></div>'}]}},
'string-methods':{intro:'Strings ship with a power toolkit: measure, peek, slice, find, compare, clean, split. Seven methods handle roughly 90% of all text work you will ever do.',question:'If books had instant tools — ruler, tweezers, scissors, finder — which would you reach for daily?',analogy:'The Swiss knife. length() the ruler, charAt() the tweezers, substring() the scissors, equals() the scale, toUpperCase() the megaphone, trim() the towel, split() the cutter. One tool per job.',analogyFail:'Where it breaks: real scissors cut the original. String scissors return FRESH paper — the original never changes (immutability, next lesson). Forgetting this discards every “edit”.',explain:['Measure & peek: <b>length()</b>, <b>charAt(i)</b> (0-based, crashes past the end like arrays), <b>indexOf(x)</b> returning −1 for “absent”.','Slice: <b>substring(start, end)</b> — start INCLUDED, end EXCLUDED. "Java".substring(0, 2) is "Ja", never "Jav".','Compare & clean: <b>equals()</b> and <b>equalsIgnoreCase()</b> for content; <b>toUpperCase()/toLowerCase()</b>; <b>trim()</b> shaves edge whitespace; <b>split(",")</b> cuts "a,b" into ["a","b"].','Case matters everywhere: equals is exact, indexOf finds exact case, and charAt(length) is out-of-bounds — text has doors too.'],tech:['<b>substring shares nothing</b> (modern JVMs copy) — but treat results as fresh strings regardless; the original is never modified.','<b>split takes a REGEX</b>, not plain text: split(".") splits on EVERYTHING (dot = any char). Escape it: split("\\\\."). A genuine trap.','<b>indexOf</b> has overloads: indexOf("a", 5) searches FROM position 5 — the backbone of find-all loops.'],code:`public class Main {\n  public static void main(String[] args) {\n    String s = "  Java Rocks  ";\n    String clean = s.trim();\n    System.out.println(clean);\n    System.out.println("len = " + clean.length());\n    System.out.println("Java vs java: " + "Java".equals("java"));\n    System.out.println("slice = " + "Java".substring(0, 2));\n    System.out.println("at = " + "Java".indexOf("v"));\n  }\n}`,codeNotes:['trim shaves edge spaces → "Java Rocks", length 10.','equals is case-exact → false.','substring(0,2) keeps 0–1 → "Ja"; indexOf("v") → 2.'],output:'Java Rocks\nlen = 10\nJava vs java: false\nslice = Ja\nat = 2',why:'Cleaned, measured, compared (case counts!), sliced with excluded end, located by position.',sim:{kind:'concat',label:'Clean text then slice it.',fields:[{v:'  Java '},{v:'Rocks'}]},mistakes:[{bad:'s == "Java" to compare words.',why:'Identity again — same content, usually different houses.',fix:'s.equals("Java") for content, always.'},{bad:'substring(0, 5) expecting FIVE inclusive chars.',why:'End index is EXCLUDED: 0..5 yields positions 0–4.',fix:'Want 5 chars? substring(0, 5) gives exactly 5 — positions 0,1,2,3,4.'},{bad:'s.trim(); then using s unchanged.',why:'trim returns a FRESH string; the call alone edits nothing.',fix:'Catch it: s = s.trim();'},{bad:'split(".") to cut on dots.',why:'split takes REGEX — "." means “any character”, shredding everything.',fix:'Escape it: split("\\\\.") — regex tax.'}],practices:[{title:'First three',task:'Take the first 3 characters of any name variable.',hint:'substring(0, 3).',sol:'name.substring(0, 3); // positions 0,1,2'},{title:'Find the @',task:'Check whether an email String contains "@".',hint:'indexOf returns −1 when absent.',sol:'email.indexOf("@") != -1;'}],quiz:[{id:'q1',prompt:'"Java".substring(0, 2) is…',options:[{t:'Ja',ok:true},{t:'Jav'},{t:'av'},{t:'avJ'}],explain:'End excluded: positions 0 and 1 only.'},{id:'q2',prompt:'indexOf for a missing piece returns…',options:[{t:'-1',ok:true},{t:'0'},{t:'null'},{t:'A crash'}],explain:'−1 is the universal “absent” signal.'},{id:'q3',prompt:'Text content compares with…',options:[{t:'equals()',ok:true},{t:'=='},{t:'='},{t:'!='}],explain:'Content check — identity need not apply.'},{id:'q4',prompt:'split(".") misbehaves because…',options:[{t:'split takes regex, and . means “any char”',ok:true},{t:'Dots are illegal'},{t:'Split needs two dots'},{t:'Strings cannot split'}],explain:'Escape the dot: split("\\\\.").'}],takeaways:['Seven tools cover nearly all text jobs.','End index excluded; −1 means absent.','Methods return fresh strings — catch them.','Case always matters; split takes regex.'],recall:'Which method finds a word’s position, and what does “absent” look like?',todo:'Clean, slice, and search your own full name three ways.',anim:{title:'Swiss knife demo',steps:[{caption:'Ruler: "Java Rocks" is 10 long.',html:'<div class="pipe"><div class="box">"Java Rocks" → 10</div></div>'},{caption:'Tweezers: charAt(0) plucks J.',html:'<div class="pipe"><div class="box">pick slot 0 → J</div></div>'},{caption:'Scissors: substring(0,2) cuts Ja.',html:'<div class="pipe"><div class="box">cut 0..2 → Ja ✂️</div></div>'}]}},
'string-immut':{intro:'Strings CANNOT change after birth. Every “edit” secretly constructs a brand-new string — wonderfully safe to share, quietly expensive in loops.',question:'Why are printed books trustworthy evidence but whiteboards are not?',analogy:'Printed book versus whiteboard. s.toUpperCase() PHOTOCOPIES the book in caps; the original book sits unchanged. The whiteboard (StringBuilder, next lesson) edits in place.',analogyFail:'Where it breaks: photocopying 10,000 pages to change one word each is madness — yet loop-concatenating with + does exactly that. Bulk edits belong on the whiteboard.',explain:['<b>Immutable</b> = zero in-place edits, ever. s.toUpperCase() RETURNS the new string; s itself is untouched unless you REASSIGN: s = s.toUpperCase();','Why design it so? Safe SHARING (no borrower can vandalize your text), thread safety, and the string POOL (identical literals share one object).','The #1 symptom: calling a method and IGNORING its return. s.trim(); alone is a no-op with extra steps — always catch the result.','Loop rule: building text piece-by-piece with + creates a photocopy per round (O(n²) time). Hundreds of rounds demand StringBuilder.'],tech:['The <b>string pool</b> reuses literals: "hi" == "hi" is often true (same pooled object) — which is precisely why == FOOLS beginners. equals() always.','Because Strings are immutable, they are <b>thread-safe by construction</b> and perfect HashMap keys.','Concatenation in a loop is <b>O(n²)</b>: each + copies everything so far. 10,000 rounds ≈ 50M char-copies. Builder stays O(n).'],code:`public class Main {\n  public static void main(String[] args) {\n    String s = "java";\n    s.toUpperCase(); // photocopy made... and dropped on the floor\n    System.out.println(s); // still "java"!\n    s = s.toUpperCase(); // NOW catch the copy\n    System.out.println(s); // "JAVA"\n  }\n}`,codeNotes:['Line 4’s result is discarded — the classic bug, live.','The original never moved.','Reassignment points s at the new string.'],output:'java\nJAVA',why:'No mutation exists; only reassignment changes which string s points at.',sim:{kind:'concat',label:'Ignored result versus saved result.',fields:[{v:'java'},{v:'!'}]},mistakes:[{bad:'s.toUpperCase(); then wondering why s is unchanged.',why:'The fresh string was built and instantly dropped.',fix:'Catch it: s = s.toUpperCase();'},{bad:'Looping s += piece 10,000 times.',why:'Ten thousand photocopies of ever-longer books — quadratic sludge.',fix:'One StringBuilder for loop-built text.'},{bad:'Trusting == after transformations.',why:'Every “edit” builds a NEW house — identity is meaningless here.',fix:'equals() for content, forever.'}],practices:[{title:'Fix the freeze',task:'Fix: s.trim(); System.out.println(s); still prints spaces.',hint:'Reassign the catch.',sol:'s = s.trim(); — then print.'},{title:'Cost it',task:'"a"+"b" per loop round × 10k vs one builder — which wins and roughly why?',hint:'Copies per round.',sol:'Builder: one board, O(n). Plus-chain: O(n²) photocopies.'}],quiz:[{id:'q1',prompt:'s.toUpperCase() without assignment leaves s…',options:[{t:'Unchanged',ok:true},{t:'Uppercase'},{t:'Deleted'},{t:'Null'}],explain:'The new string was built and dropped.'},{id:'q2',prompt:'Strings are immutable mainly for…',options:[{t:'Safe sharing, pooling, thread-safety',ok:true},{t:'Annoying beginners'},{t:'Saving keystrokes'},{t:'No reason at all'}],explain:'Share without fear — nobody can vandalize your text.'},{id:'q3',prompt:'Building 10k pieces in a loop needs…',options:[{t:'StringBuilder',ok:true},{t:'+ on String'},{t:'char =='},{t:'System.exit'}],explain:'One whiteboard beats ten thousand photocopies.'},{id:'q4',prompt:'"hi" == "hi" is often true because…',options:[{t:'Literals share one pooled object',ok:true},{t:'== compares content'},{t:'All strings are identical'},{t:'Luck'}],explain:'The pool reuses literals — which is exactly why == fools people.'}],takeaways:['Strings never mutate — methods return new ones.','Always catch the returned string.','Loop-built text belongs to StringBuilder.','Pooling explains == illusions; use equals.'],recall:'What physically happens to the original string in s + "!"?',todo:'Find one ignored string-result in your old code and fix it with reassignment.',anim:{title:'Photocopy semantics',steps:[{caption:'Book "java" printed and shelved.',html:'<div class="pipe"><div class="box"><b>"java"</b> 📕</div></div>'},{caption:'toUpperCase photocopies it.',html:'<div class="pipe"><div class="box">"java"</div><span class="arr">→</span><div class="box"><b>"JAVA"</b> 📄 new</div></div>'},{caption:'s still points at the OLD book.',html:'<div class="pipe"><div class="box">s → "java" (old)</div></div>'}]}},
'stringbuilder':{intro:'StringBuilder is the whiteboard for text: scribble, append, erase in place — then photograph it (toString) when the final text is ready.',question:'How do you collect 1,000 signatures without shuffling 1,000 papers?',analogy:'The whiteboard list. Append one more line per visitor, erase typos in place, photograph the board at closing time for the printed record (String). One board, zero photocopies.',analogyFail:'Where it breaks: whiteboards are NOT for strangers to share across threads (not synchronized — fine for our single-thread apps) and a Builder is NOT a String: handing sb where text is wanted fails to compile.',explain:['Cycle: <b>new StringBuilder()</b> → chain <b>.append(x)</b> (any type!) → finish with <b>.toString()</b>. The SAME object grows throughout.','More tools: <b>length()</b>, <b>charAt/setCharAt</b>, <b>delete(a,b)</b>, <b>insert(at, x)</b>, <b>reverse()</b> — all editing the one board in place.','Rule: loop-built or heavily-edited text → Builder. One-off joins of a FEW pieces → plain + is fine and reads better.','Convert explicitly: String done = sb.toString();. Comparing needs the photo too: sb.toString().equals("...") — Builder’s own equals is identity.'],tech:['<b>append returns THIS</b> (the same builder), enabling chains: sb.append(a).append(b). No new objects per link.','Builders pre-size a <b>capacity buffer</b> (default 16 + growth) so appends rarely reallocate — the engineering behind the speed.','Need thread-safe sharing? <b>StringBuffer</b> is the synchronized twin — slower, rarely needed. Default to Builder.'],code:`public class Main {\n  public static void main(String[] args) {\n    StringBuilder sb = new StringBuilder();\n    for (int i = 1; i <= 3; i++) {\n      sb.append(i).append(" ");\n    }\n    System.out.println("built = " + sb.toString());\n    sb.reverse(); // edits the SAME board, in place!\n    System.out.println("flipped = " + sb.toString());\n  }\n}`,codeNotes:['One object absorbs all three appends.','toString photographs the board.','reverse flips the board itself — no copy.'],output:'built = 1 2 3 \nflipped =  3 2 1',why:'Appends mutate the single builder; reverse flips it in place; each photo shows the current board.',sim:{kind:'concat',label:'Append pieces onto the board.',fields:[{v:'1 2 '},{v:'3'}]},mistakes:[{bad:'String s = sb; — type mismatch.',why:'A Builder is NOT a String, however similar they feel.',fix:'Photograph it: String s = sb.toString();'},{bad:'+ chains inside a big loop “because shorter”.',why:'Shorter to type, quadratic to run — copies every round.',fix:'One builder outside, appends inside.'},{bad:'sb.equals("...") to compare content.',why:'Builder never overrode equals — identity again.',fix:'Compare the photo: sb.toString().equals("...").'}],practices:[{title:'CSV line',task:'Build the string "1,2,3," from numbers 1–3 with a builder.',hint:'append(i).append(",") per round.',sol:'StringBuilder sb = new StringBuilder(); for (...) sb.append(i).append(","); String s = sb.toString();'},{title:'Fix the loop',task:'Rewrite this with a builder: String s = ""; for (...) s += word;',hint:'One sb outside the loop.',sol:'StringBuilder sb = new StringBuilder(); for (...) sb.append(word); String s = sb.toString();'}],quiz:[{id:'q1',prompt:'A builder becomes a String via…',options:[{t:'toString()',ok:true},{t:'equals()'},{t:'append()'},{t:'A cast'}],explain:'The snapshot photo of the board.'},{id:'q2',prompt:'Appends across loop rounds edit…',options:[{t:'The same object (mutable)',ok:true},{t:'A fresh copy each time'},{t:'Nothing at all'},{t:'The console directly'}],explain:'One whiteboard, growing in place.'},{id:'q3',prompt:'Builder vs + inside big loops?',options:[{t:'Builder: linear, far less garbage',ok:true},{t:'+ is faster there'},{t:'Identical cost'},{t:'Neither works'}],explain:'One board versus O(n²) photocopies.'},{id:'q4',prompt:'append(x) returns…',options:[{t:'The same builder (chainable)',ok:true},{t:'A new builder'},{t:'A String'},{t:'Nothing (void)'}],explain:'THIS comes back — chains cost nothing.'}],takeaways:['Builder = the mutable text whiteboard.','append chains; toString photographs.','Default for loop-built or edited text.','Small fixed joins: plain + reads better.'],recall:'When MUST you pick Builder over + ? When is + fine?',todo:'Rewrite one loop-concat in your old code with a Builder.',anim:{title:'Whiteboard workflow',steps:[{caption:'Empty board, marker ready.',html:'<div class="pipe"><div class="box">board: ""</div></div>'},{caption:'Append 1, 2, 3 — same board.',html:'<div class="pipe"><div class="box">board: "1 2 3 " ✏️</div></div>'},{caption:'Photograph it → String. 📸',html:'<div class="pipe"><div class="box">toString → "1 2 3 " 📸</div></div>'}]}},
'algorithms-basic':{intro:'Four tiny superpowers from ONE loop skeleton: find the biggest, find the smallest, count the matches, locate an item. Learn the skeleton once; the “memory” you keep is the only thing that changes.',question:'How do you find the tallest student in a line without measuring anyone twice?',analogy:'The trophy walk. Crown the first student champion (best so far), walk the line, swap crowns whenever someone taller appears. Counting = clicker per match. Searching = stop at the first name called.',analogyFail:'Where it breaks: an EMPTY line has no first student — crowning a[0] of nothing crashes. Empty input is the edge case every algorithm must answer.',explain:['<b>Max/min</b>: crown best = a[0], tour the REST, swap on strictly-better. Initializing to 0 instead breaks on all-negative inputs — crown a REAL contender.','<b>Counting</b>: clicker c = 0, c++ on every match. <b>Linear search</b>: walk, return the index on match, <b>−1</b> for “absent” (−1 can never be a valid index, so it is unambiguous).','Stop early when the answer is final: search returns the moment it finds; max/min must finish the whole line (a taller student could be last).','All three share ONE skeleton: init memory → tour every slot → update memory → report. New problem? Same skeleton, different memory. That is the transferable skill.'],tech:['These are <b>O(n)</b>: work grows linearly with input size — twice the students, twice the steps. Your first complexity class, felt not memorized.','<b>Sentinel values</b>: −1 for “not found”, 0 for “none counted”. Pick values OUTSIDE the answer domain so “absent” never mimics a result.','Empty arrays need an explicit decision: throw, return −1/Optional, or require non-empty. “a[0] and pray” is the bug.'],code:`public class Main {\n  public static void main(String[] args) {\n    int[] a = {4, 9, 2, 9};\n    int max = a[0];   // crown the first contender\n    int count9 = 0;   // clicker for nines\n    int pos2 = -1;    // sentinel: not found yet\n    for (int i = 0; i < a.length; i++) {\n      if (a[i] > max) max = a[i];\n      if (a[i] == 9) count9++;\n      if (a[i] == 2) pos2 = i;\n    }\n    System.out.println("max = " + max);\n    System.out.println("nines = " + count9);\n    System.out.println("first 2 at = " + pos2);\n  }\n}`,codeNotes:['The champion starts as a REAL element, not 0.','Each slot is tested once, three memories updated.','Results: max 9, two nines, 2 sits at index 2.'],output:'max = 9\nnines = 2\nfirst 2 at = 2',why:'One walk collects three answers — same skeleton, three different memories. 4 crowns, 9 dethrones, 2 and 9 counted and located.',sim:{kind:'array',label:'Search doors 0–3 for the target.',fields:[{v:'2'}]},mistakes:[{bad:'max = 0 “to be safe” with all-negative data.',why:'0 outranks −5 — the “champion” never fought anyone.',fix:'Crown a real contender: max = a[0].'},{bad:'Crowning a[0] of an EMPTY array.',why:'No first student exists — crash on step one.',fix:'Decide empty up front: if (a.length == 0) ... handle.'},{bad:'Returning 0 for “not found”.',why:'0 LOOKS like “found at slot 0” — ambiguity bug.',fix:'Sentinel −1: outside every valid index.'},{bad:'Counting with an uninitialized clicker.',why:'Locals have no defaults — compile error.',fix:'int count = 0; before the tour.'}],practices:[{title:'Find the min',task:'Find the minimum of {4, 9, 2, 9} using the skeleton.',hint:'Mirror max with <, crown a[0].',sol:'min ends at 2.'},{title:'Count the evens',task:'Count even numbers in any int array.',hint:'% 2 == 0 → click.',sol:'int c = 0; for (int v : a) if (v % 2 == 0) c++;'}],quiz:[{id:'q1',prompt:'Max over unknown values initializes to…',options:[{t:'a[0] (a real contender)',ok:true},{t:'0, always'},{t:'999999'},{t:'-1'}],explain:'Crown someone real — 0 loses to negatives.'},{id:'q2',prompt:'Search with no match returns…',options:[{t:'-1',ok:true},{t:'0'},{t:'null'},{t:'The length'}],explain:'−1 lives outside every valid index.'},{id:'q3',prompt:'The program above prints…',options:[{t:'max = 9, nines = 2, first 2 at = 2',ok:true},{t:'max = 4, nines = 1, first 2 at = 0'},{t:'max = 9, nines = 1, first 2 at = 2'},{t:'max = 2, nines = 2, first 2 at = 9'}],explain:'Walk it: 4 crowns, 9 dethrones + clicks, 2 locates, 9 clicks.'},{id:'q4',prompt:'max = 0 fails on {-5, -3} because…',options:[{t:'0 outranks all real candidates',ok:true},{t:'Negatives crash loops'},{t:'0 is not an integer'},{t:'Arrays hate zero'}],explain:'The fake champion never loses — wrong answer, no error.'}],takeaways:['One skeleton: init memory → tour → update → report.','Crown real contenders; sentinel −1 means absent.','Decide the empty case explicitly.','Feel O(n): double input, double steps.'],recall:'What are the three “memories” (inits) for max / count / search?',todo:'Find the min AND count of 5s in your own ages array.',anim:{title:'Trophy walk',steps:[{caption:'Crown student one: 4. 🏆',html:'<div class="viz"><div class="varbox"><div class="nm">🏆 max</div><div class="vl">4</div></div></div>'},{caption:'Student two (9) dethrones!',html:'<div class="viz"><div class="varbox"><div class="nm">🏆 max</div><div class="vl">9 ✨</div></div></div>'},{caption:'Clicker: two nines counted. Done.',html:'<div class="viz"><div class="varbox"><div class="nm">count9</div><div class="vl">2</div></div></div>'}]}},
};
